window.LEVEL_DATA["A1"] = {"st-01":{"intro":"Bir kahve molasında şirketini çok basit cümlelerle tanıtıyorsun.","text":[{"who":"Partner","en":"Hello, what does your company do?","tr":"Merhaba, şirketiniz ne yapıyor?"},{"who":"Me","en":"We are a medical technology startup from Turkey.","tr":"Biz Türkiye'den bir medikal teknoloji girişimiyiz."},{"who":"Me","en":"We make a device that tests hearing.","tr":"İşitmeyi test eden bir cihaz yapıyoruz."},{"who":"Partner","en":"Who are your customers?","tr":"Müşterileriniz kimler?"},{"who":"Me","en":"Our customers are hospitals, clinics and hearing aid shops.","tr":"Müşterilerimiz hastaneler, klinikler ve işitme cihazı mağazaları."},{"who":"Me","en":"They do not have enough experts.","tr":"Yeterli uzmanları yok."},{"who":"Me","en":"We are a small team of six people.","tr":"Altı kişilik küçük bir ekibiz."},{"who":"Me","en":"I am here to find partners in Europe.","tr":"Avrupa'da ortak bulmak için buradayım."}],"vocab":[{"en":"startup","tr":"girişim","ex":"We are a startup from Turkey.","def":"a new, small company"},{"en":"device","tr":"cihaz","ex":"We make a device that tests hearing.","def":"a machine or tool"},{"en":"customer","tr":"müşteri","ex":"Our customers are hospitals and clinics.","def":"a person or company that buys from you"},{"en":"expert","tr":"uzman","ex":"They do not have enough experts.","def":"a person who knows a lot about one thing"},{"en":"team","tr":"ekip","ex":"We are a small team of six people.","def":"a group of people who work together"},{"en":"partner","tr":"ortak, iş ortağı","ex":"I am here to find partners in Europe.","def":"a person or company you work with"}],"grammar":{"title":"To be: am / is / are","tr":"Kim ya da ne olduğumuzu söylemek için 'to be' kullanırız: I am, we are, they are. Olumsuz cümlede 'not' ekleriz: They are not.","examples":["We are a medical technology startup.","Our customers are hospitals and clinics.","I am here to find partners."]},"questions":[{"q":"Where is the startup from?","options":["Germany","Turkey","Spain"],"a":1},{"q":"How many people are in the team?","options":["Six","Three","Ten"],"a":0},{"q":"Who are the customers?","options":["Schools","Banks","Hospitals, clinics and hearing aid shops"],"a":2}],"gaps":[{"s":"We make a ___ that tests hearing.","a":"device","hint":"cihaz"},{"s":"Our ___ are hospitals, clinics and hearing aid shops.","a":"customers","hint":"müşteriler"},{"s":"We are a small ___ of six people.","a":"team","hint":"ekip"}],"order":[{"a":"We are a small team of six people."},{"a":"I am here to find partners in Europe."}],"translate":[{"tr":"Biz küçük bir ekibiz.","en":"We are a small team.","keys":["small team"]},{"tr":"İşitmeyi test eden bir cihaz yapıyoruz.","en":"We make a device that tests hearing.","keys":["device","tests hearing"]}],"roleplay":{"persona":"Potential partner","personaTr":"Olası iş ortağı","scene":"Bir konferansta kahve molasında Almanya'dan bir klinik zinciri yöneticisiyle tanışıyorsun.","turns":[{"ai":"Hello! What does your company do?","aiTr":"Merhaba! Şirketiniz ne yapıyor?","hint":"We make a device that tests hearing.","keys":["device","hearing","test"]},{"ai":"Who are your customers?","aiTr":"Müşterileriniz kimler?","hint":"Our customers are hospitals, clinics and hearing aid shops.","keys":["hospital","clinic","customer"]},{"ai":"Why are you here?","aiTr":"Neden buradasınız?","hint":"I am here to find partners in Europe.","keys":["partner","Europe"]}]}},"ai-01":{"intro":"Cihazını çok basit cümlelerle, adım adım anlatıyorsun.","text":[{"en":"An audiometer is a device for hearing tests.","tr":"Odyometre, işitme testleri için kullanılan bir cihazdır."},{"en":"A normal test needs an expert and about thirty minutes.","tr":"Normal bir test için bir uzman ve yaklaşık otuz dakika gerekir."},{"en":"Our audiometer is autonomous: it does not need an expert.","tr":"Bizim odyometremiz otonom: uzmana ihtiyaç duymuyor."},{"en":"The patient puts on the headphones.","tr":"Hasta kulaklıkları takar."},{"en":"When the patient hears a sound, they press a button.","tr":"Hasta bir ses duyduğunda bir düğmeye basar."},{"en":"The AI changes the test in real time.","tr":"Yapay zekâ testi anında uyarlar."},{"en":"At the end, the device makes an audiogram.","tr":"Sonunda cihaz bir odyogram oluşturur."},{"en":"The test takes less than ten minutes.","tr":"Test on dakikadan kısa sürer."}],"vocab":[{"en":"headphones","tr":"kulaklık","ex":"The patient puts on the headphones."},{"en":"press a button","tr":"düğmeye basmak","ex":"Press the button when you hear a sound."},{"en":"expert","tr":"uzman","ex":"We do not need an expert."},{"en":"autonomous","tr":"otonom, kendi kendine çalışan","ex":"Our device is autonomous."},{"en":"audiogram","tr":"odyogram (işitme grafiği)","ex":"The device makes an audiogram."},{"en":"less than","tr":"...den az","ex":"It takes less than ten minutes."}],"grammar":{"title":"Present simple: how something works","tr":"Bir şeyin nasıl çalıştığını anlatırken present simple kullanılır. he / she / it ile fiil -s alır: it makes, the patient presses.","examples":["The patient puts on the headphones.","The device makes an audiogram.","The test takes less than ten minutes."]},"questions":[{"q":"What does the patient put on?","options":["Glasses","Headphones","A watch"],"a":1},{"q":"What does the patient do when they hear a sound?","options":["They press a button","They say yes","They stand up"],"a":0},{"q":"How long does the test take?","options":["About thirty minutes","One hour","Less than ten minutes"],"a":2}],"gaps":[{"s":"The patient puts on the ___.","a":"headphones","hint":"kulaklık"},{"s":"When the patient hears a sound, they press a ___.","a":"button","hint":"düğme"},{"s":"The test takes less than ten ___.","a":"minutes","hint":"dakika"}],"order":[{"a":"The patient puts on the headphones."},{"a":"The test takes less than ten minutes."}],"translate":[{"tr":"Uzmana ihtiyacımız yok.","en":"We do not need an expert.","keys":["need","expert"]},{"tr":"Test on dakikadan kısa sürer.","en":"The test takes less than ten minutes.","keys":["less than","ten minutes"]}],"roleplay":{"persona":"Curious doctor","personaTr":"Meraklı doktor","scene":"Bir fuarda İngiliz bir kulak burun boğaz doktoru standına gelip cihazını soruyor.","turns":[{"ai":"Hello! What is this device?","aiTr":"Merhaba! Bu cihaz ne?","hint":"It is an audiometer. It tests hearing.","keys":["audiometer","hearing"]},{"ai":"How does it work?","aiTr":"Nasıl çalışıyor?","hint":"The patient puts on the headphones and presses a button.","keys":["headphones","button","press"]},{"ai":"Is it fast?","aiTr":"Hızlı mı?","hint":"Yes. The test takes less than ten minutes.","keys":["less than","ten minutes","minutes"]}]}},"co-01":{"intro":"Bir konferansta yeni biriyle tanışıyor ve kendini kısaca tanıtıyorsun.","text":[{"who":"Me","en":"Hi, my name is {name}.","tr":"Merhaba, benim adım {name}."},{"who":"Sarah","en":"Hello {name}, I'm Sarah from a UK hospital group.","tr":"Merhaba {name}, ben Sarah, İngiltere'deki bir hastane grubundanım."},{"who":"Me","en":"I am the founder of a startup from Turkey.","tr":"Ben Türkiye'den bir girişimin kurucusuyum."},{"who":"Me","en":"We make a device that tests hearing without an expert.","tr":"Uzman olmadan işitmeyi test eden bir cihaz yapıyoruz."},{"who":"Sarah","en":"We have long waiting lists for hearing tests.","tr":"İşitme testleri için uzun bekleme listelerimiz var."},{"who":"Me","en":"That is the problem we solve.","tr":"Bizim çözdüğümüz sorun tam da bu."},{"who":"Me","en":"Here is my card.","tr":"Buyurun, kartım."},{"who":"Sarah","en":"Thanks, let's talk after the next session.","tr":"Teşekkürler, bir sonraki oturumdan sonra konuşalım."}],"vocab":[{"en":"founder","tr":"kurucu","ex":"I am the founder of a startup."},{"en":"startup","tr":"girişim","ex":"My startup is from Turkey."},{"en":"hearing test","tr":"işitme testi","ex":"The device does a hearing test."},{"en":"waiting list","tr":"bekleme listesi","ex":"The waiting list is very long."},{"en":"card","tr":"kartvizit","ex":"Here is my card."},{"en":"session","tr":"oturum","ex":"Let's talk after the next session."}],"grammar":{"title":"To be: I am, it is","tr":"Kendini tanıtırken 'to be' fiili kullanılır: I am, you are, he/she/it is. Konuşmada genelde kısaltılır: I'm, it's, that's.","examples":["I am the founder of a startup.","I'm Sarah.","That is the problem we solve."]},"questions":[{"q":"Where does Sarah work?","options":["At a startup in Turkey","At a hospital group in the UK","At a university"],"a":1},{"q":"What does the device test?","options":["Hearing","Eyes","Blood"],"a":0},{"q":"When do they want to talk again?","options":["Tomorrow","Next week","After the next session"],"a":2}],"gaps":[{"s":"I am the ___ of a startup from Turkey.","a":"founder","hint":"kurucu"},{"s":"We have long waiting ___ for hearing tests.","a":"lists","hint":"listeler"},{"s":"Here is my ___.","a":"card","hint":"kartvizit"}],"order":[{"a":"We make a device that tests hearing without an expert."},{"a":"That is the problem we solve."}],"translate":[{"tr":"Ben bir girişimin kurucusuyum.","en":"I am the founder of a startup.","keys":["founder","startup"]},{"tr":"Buyurun, kartım.","en":"Here is my card.","keys":["my card"]}],"roleplay":{"persona":"Conference guest","personaTr":"Konferans katılımcısı","scene":"Kahve molasında biri seninle konuşuyor. Kendini kısaca tanıt.","turns":[{"ai":"Hi, I'm Emma. What's your name?","aiTr":"Merhaba, ben Emma. Adınız ne?","hint":"Hi Emma, my name is {name}. Nice to meet you.","keys":["my name is","nice to meet you"]},{"ai":"Nice to meet you. What do you do?","aiTr":"Tanıştığımıza memnun oldum. Ne iş yapıyorsunuz?","hint":"I am the founder of a startup from Turkey. We make a hearing test device.","keys":["founder","startup","hearing"]},{"ai":"Oh, we have long waiting lists in our clinics.","aiTr":"Aa, kliniklerimizde uzun bekleme listeleri var.","hint":"That is the problem we solve. Here is my card.","keys":["problem we solve","my card"]}]}},"ab-01":{"intro":"Berlin'de bir daireye bakıyorsun ve ev sahibine kira, depozito ve tarih hakkında basit sorular soruyorsun.","text":[{"who":"Landlord","en":"Hello, please come in and look around.","tr":"Merhaba, buyurun girin, etrafa bakın."},{"who":"Me","en":"Thank you, the flat is very nice and bright.","tr":"Teşekkürler, daire çok güzel ve aydınlık."},{"who":"Me","en":"How much is the rent per month?","tr":"Aylık kira ne kadar?"},{"who":"Landlord","en":"It is €1,200, with heating and water included.","tr":"1.200 avro; ısınma ve su dahil."},{"who":"Me","en":"Is the internet included too?","tr":"İnternet de dahil mi?"},{"who":"Landlord","en":"No, and the deposit is three months' rent.","tr":"Hayır; depozito da üç aylık kira."},{"who":"Me","en":"Can I pay the deposit in three parts?","tr":"Depozitoyu üç taksitte ödeyebilir miyim?"},{"who":"Landlord","en":"Yes, and the flat is free from 1 November.","tr":"Evet; daire de 1 Kasım'dan itibaren boş."}],"vocab":[{"en":"flat","tr":"daire","ex":"The flat is very nice and bright."},{"en":"rent","tr":"kira","ex":"The rent is €1,200 per month."},{"en":"per month","tr":"aylık, ayda","ex":"How much is it per month?"},{"en":"included","tr":"dahil","ex":"Heating and water are included."},{"en":"deposit","tr":"depozito","ex":"The deposit is three months' rent."},{"en":"proof of income","tr":"gelir belgesi","ex":"Please bring your passport and proof of income."}],"grammar":{"title":"Questions with 'to be': Is it…? How much is…?","tr":"'To be' ile soru sorarken 'is/are' fiilini öne alırız: 'The internet is included' → 'Is the internet included?' Soru kelimesi varsa en başa gelir: 'How much is the rent?'","examples":["Is the internet included?","How much is the rent per month?","Is the flat free in November?"]},"questions":[{"q":"How much is the rent per month?","options":["€1,000","€1,200","€3,600"],"a":1},{"q":"Is the internet included?","options":["No","Yes","Only in November"],"a":0},{"q":"When is the flat free?","options":["In October","In December","From 1 November"],"a":2}],"gaps":[{"s":"How much is the ___ per month?","a":"rent","hint":"kira"},{"s":"Heating and water are ___.","a":"included","hint":"dahil"},{"s":"Can I pay the ___ in three parts?","a":"deposit","hint":"depozito"}],"order":[{"a":"How much is the rent per month?"},{"a":"Can I pay the deposit in three parts?"}],"translate":[{"tr":"İnternet dahil mi?","en":"Is the internet included?","keys":["internet","included"]},{"tr":"Daire kasımdan itibaren boş.","en":"The flat is free from November.","keys":["flat","free","November"]}],"roleplay":{"persona":"Landlord","personaTr":"Ev sahibi","scene":"Berlin'de bir daireye bakıyorsun. Ev sahibi Bayan Becker sana birkaç soru soruyor.","turns":[{"ai":"Hello! Do you like the flat?","aiTr":"Merhaba! Daireyi beğendiniz mi?","hint":"Yes, I like it, and it is very bright.","keys":["like","bright","nice"]},{"ai":"Do you have a passport and proof of income?","aiTr":"Pasaportunuz ve gelir belgeniz var mı?","hint":"Yes, I have my passport and my company papers.","keys":["passport","company papers","yes"]},{"ai":"Do you have pets?","aiTr":"Evcil hayvanınız var mı?","hint":"No, I don't have pets.","keys":["no","pets"]}]}},"ai-02":{"intro":"Şirketini neden kurduğunu çok basit cümlelerle anlatıyorsun.","text":[{"en":"One in five people has some hearing loss.","tr":"Her beş kişiden birinde bir miktar işitme kaybı var."},{"en":"But many of them never have a hearing test.","tr":"Ama birçoğu hiç işitme testi yaptırmıyor."},{"en":"There are not enough experts to do the tests.","tr":"Testleri yapacak yeterli uzman yok."},{"en":"In small towns, people wait months for a test.","tr":"Küçük kasabalarda insanlar bir test için aylarca bekliyor."},{"en":"Our idea is simple: a machine can do the test.","tr":"Fikrimiz basit: bir makine bu testi yapabilir."},{"en":"That idea is now AIHEAR.","tr":"O fikir bugün AIHEAR."},{"en":"We want hearing tests for everyone, everywhere.","tr":"Herkes için, her yerde işitme testi istiyoruz."},{"en":"We are from Turkey, but the problem is global.","tr":"Türkiye'deniz ama sorun küresel."}],"vocab":[{"en":"hearing loss","tr":"işitme kaybı","ex":"Many people have hearing loss."},{"en":"expert","tr":"uzman","ex":"There are not enough experts."},{"en":"small town","tr":"küçük kasaba","ex":"People in small towns wait a long time."},{"en":"wait for","tr":"...i beklemek","ex":"People wait months for a test."},{"en":"machine","tr":"makine","ex":"A machine can do the test."},{"en":"global","tr":"küresel","ex":"The problem is global."}],"grammar":{"title":"There is / there are","tr":"Bir şeyin var olup olmadığını söylerken 'there is' (tekil) ve 'there are' (çoğul) kullanılır. Olumsuzu: there is not / there are not.","examples":["There are not enough experts.","There is a simple idea.","There are many small towns in Turkey."]},"questions":[{"q":"How many people have some hearing loss?","options":["One in five","One in fifty","One in a hundred"],"a":0},{"q":"Why do many people never have a test?","options":["The test is too long","There are not enough experts","They do not want a test"],"a":1},{"q":"Where is the company from?","options":["Germany","The USA","Turkey"],"a":2}],"gaps":[{"s":"One in five people has some hearing ___.","a":"loss","hint":"kayıp"},{"s":"There are not enough ___ to do the tests.","a":"experts","hint":"uzmanlar"},{"s":"We are from Turkey, but the problem is ___.","a":"global","hint":"küresel"}],"order":[{"a":"There are not enough experts to do the tests."},{"a":"We want hearing tests for everyone."}],"translate":[{"tr":"Sorun küresel.","en":"The problem is global.","keys":["problem","global"]},{"tr":"Biz Türkiye'deniz.","en":"We are from Turkey.","keys":["from Turkey"]}],"roleplay":{"persona":"Journalist","personaTr":"Gazeteci","scene":"Bir teknoloji gazetecisi kısa bir röportajda AIHEAR'ın hikâyesini soruyor.","turns":[{"ai":"What is the problem?","aiTr":"Sorun ne?","hint":"One in five people has hearing loss, but there are not enough experts.","keys":["hearing loss","experts","not enough"]},{"ai":"What is your idea?","aiTr":"Fikriniz ne?","hint":"A machine can do the hearing test.","keys":["machine","test"]},{"ai":"Where is your company from?","aiTr":"Şirketiniz nereden?","hint":"We are from Turkey, but the problem is global.","keys":["Turkey","global"]}]}},"st-02":{"intro":"Ekibini nasıl yönettiğini çok basit cümlelerle anlatıyorsun.","text":[{"en":"I have a small team of six people.","tr":"Altı kişilik küçük bir ekibim var."},{"en":"We have a short meeting every Monday morning.","tr":"Her pazartesi sabahı kısa bir toplantı yaparız."},{"en":"Everyone talks about their work and their problems.","tr":"Herkes kendi işinden ve sorunlarından bahseder."},{"en":"I give clear tasks with a deadline.","tr":"Son tarihi olan net görevler veririm."},{"en":"When there is a problem, we fix it together.","tr":"Bir sorun olduğunda onu birlikte çözeriz."},{"en":"I do not blame my team.","tr":"Ekibimi suçlamam."},{"en":"I listen more than I talk.","tr":"Konuştuğumdan daha çok dinlerim."},{"en":"I trust my team because they are experts.","tr":"Ekibime güvenirim çünkü onlar uzman."}],"vocab":[{"en":"team","tr":"ekip","ex":"I have a small team of six people.","def":"a group of people who work together"},{"en":"meeting","tr":"toplantı","ex":"We have a short meeting every Monday.","def":"a time when people meet to talk about work"},{"en":"task","tr":"görev","ex":"I give clear tasks.","def":"a piece of work to do"},{"en":"deadline","tr":"son tarih","ex":"Every task has a deadline.","def":"the day when work must be finished"},{"en":"listen","tr":"dinlemek","ex":"I listen more than I talk.","def":"to pay attention to what someone says"},{"en":"trust","tr":"güvenmek","ex":"I trust my team.","def":"to believe that someone is good and honest"}],"grammar":{"title":"Present simple: things I do every week","tr":"Düzenli yaptığımız şeyler için present simple kullanırız: I give, we have. He, she, it ve 'everyone' ile fiile -s ekleriz: everyone talks.","examples":["We have a short meeting every Monday morning.","Everyone talks about their work.","I give clear tasks with a deadline."]},"questions":[{"q":"When is the team meeting?","options":["Every Friday evening","Every Monday morning","Every day"],"a":1},{"q":"How many people are in the team?","options":["Six","Two","Twelve"],"a":0},{"q":"What do they do when there is a problem?","options":["They stop working","They call a doctor","They fix it together"],"a":2}],"gaps":[{"s":"I give clear tasks with a ___.","a":"deadline","hint":"son tarih"},{"s":"We have a short ___ every Monday morning.","a":"meeting","hint":"toplantı"},{"s":"I ___ my team because they are experts.","a":"trust","hint":"güvenmek"}],"order":[{"a":"We have a short meeting every Monday morning."},{"a":"I listen more than I talk."}],"translate":[{"tr":"Ekibime güvenirim.","en":"I trust my team.","keys":["trust","my team"]},{"tr":"Her pazartesi sabahı bir toplantı yaparız.","en":"We have a meeting every Monday morning.","keys":["meeting","Monday morning"]}],"roleplay":{"persona":"New engineer","personaTr":"Yeni mühendis","scene":"Ekibe bu hafta katılan yeni mühendis, nasıl çalıştığınızı soruyor.","turns":[{"ai":"Hi! How does the team work?","aiTr":"Merhaba! Ekip nasıl çalışıyor?","hint":"We have a short meeting every Monday morning.","keys":["meeting","Monday"]},{"ai":"I have a problem with my task. What do I do?","aiTr":"Görevimle ilgili bir sorunum var. Ne yapayım?","hint":"Tell me, and we fix it together.","keys":["together","fix","tell"]},{"ai":"What is my first task?","aiTr":"İlk görevim ne?","hint":"Please finish the test report by Friday.","keys":["report","Friday","finish"]}]}},"te-01":{"intro":"Yapay zekânın sağlıkta ne işe yaradığını çok basit cümlelerle anlatıyorsun.","text":[{"en":"AI is changing healthcare.","tr":"Yapay zekâ sağlık hizmetlerini değiştiriyor."},{"en":"AI can look at thousands of images very fast.","tr":"Yapay zekâ binlerce görüntüye çok hızlı bakabilir."},{"en":"It can help doctors find problems in X-rays.","tr":"Doktorların röntgenlerdeki sorunları bulmasına yardım edebilir."},{"en":"AI does not get tired.","tr":"Yapay zekâ yorulmaz."},{"en":"But AI is not perfect, and it can make mistakes.","tr":"Ama yapay zekâ mükemmel değil ve hata yapabilir."},{"en":"So a doctor always checks the result.","tr":"Bu yüzden sonucu her zaman bir doktor kontrol eder."},{"en":"In our company, AI makes hearing tests fast and easy.","tr":"Şirketimizde yapay zekâ işitme testlerini hızlı ve kolay hale getiriyor."},{"en":"A hearing test with our device takes under ten minutes.","tr":"Cihazımızla bir işitme testi on dakikadan kısa sürüyor."}],"vocab":[{"en":"healthcare","tr":"sağlık hizmetleri","ex":"AI is changing healthcare."},{"en":"image","tr":"görüntü","ex":"AI can look at thousands of images."},{"en":"get tired","tr":"yorulmak","ex":"AI does not get tired."},{"en":"make a mistake","tr":"hata yapmak","ex":"AI can make mistakes."},{"en":"check","tr":"kontrol etmek","ex":"A doctor checks the result."},{"en":"result","tr":"sonuç","ex":"The result is ready in ten minutes."}],"grammar":{"title":"Present simple: it + -s","tr":"He, she, it ile present simple'da fiile -s eklenir: it makes, it takes, a doctor checks. Olumsuzda 'does not' + yalın fiil kullanılır: It does not get tired.","examples":["A doctor always checks the result.","AI makes hearing tests fast.","AI does not get tired."]},"questions":[{"q":"What can AI look at very fast?","options":["Emails","Thousands of images","Hospital bills"],"a":1},{"q":"Who checks the result?","options":["The patient","A computer","A doctor"],"a":2},{"q":"How long does a hearing test with the device take?","options":["Under ten minutes","One hour","One day"],"a":0}],"gaps":[{"s":"AI does not get ___.","a":"tired","hint":"yorgun"},{"s":"But AI is not perfect, and it can make ___.","a":"mistakes","hint":"hatalar"},{"s":"So a doctor always ___ the result.","a":"checks","hint":"kontrol eder"}],"order":[{"a":"AI is changing healthcare."},{"a":"It can help doctors find problems in X-rays."}],"translate":[{"tr":"Yapay zekâ yorulmaz.","en":"AI does not get tired.","keys":["tired"]},{"tr":"Sonucu bir doktor kontrol eder.","en":"A doctor checks the result.","keys":["doctor","checks","result"]}],"roleplay":{"persona":"Doctor","personaTr":"Doktor","scene":"Bir doktor yapay zekânın hastanede ne işe yaradığını soruyor.","turns":[{"ai":"Why do we need AI? We have doctors.","aiTr":"Neden yapay zekâya ihtiyacımız var? Doktorlarımız var.","hint":"AI is very fast, and it does not get tired.","keys":["fast","tired"]},{"ai":"Does AI make mistakes?","aiTr":"Yapay zekâ hata yapar mı?","hint":"Yes, it can make mistakes, so a doctor always checks the result.","keys":["mistakes","checks","doctor"]},{"ai":"What does AI do in your device?","aiTr":"Cihazınızda yapay zekâ ne yapıyor?","hint":"It makes hearing tests fast and easy.","keys":["hearing tests","fast","easy"]}]}},"li-01":{"intro":"İş seyahatindesin: pasaport kontrolünde ve otel resepsiyonunda çok basit cümleler kuruyorsun.","text":[{"who":"Officer","en":"Hello, why are you here?","tr":"Merhaba, neden buradasınız?"},{"who":"Me","en":"I am here for a business conference.","tr":"Bir iş konferansı için buradayım."},{"who":"Officer","en":"How long are you here for?","tr":"Ne kadar süre buradasınız?"},{"who":"Me","en":"I am here for four days.","tr":"Dört gün buradayım."},{"who":"Me","en":"Hello, I have a reservation under the name {name}.","tr":"Merhaba, {name} adına bir rezervasyonum var."},{"who":"Receptionist","en":"Can I see your passport, please?","tr":"Pasaportunuzu görebilir miyim, lütfen?"},{"who":"Me","en":"Yes, of course, and is breakfast included?","tr":"Evet, tabii; kahvaltı dahil mi?"},{"who":"Receptionist","en":"Yes, and your room is on the fifth floor.","tr":"Evet, odanız da beşinci katta."}],"vocab":[{"en":"business conference","tr":"iş konferansı","ex":"I am here for a business conference."},{"en":"reservation","tr":"rezervasyon","ex":"I have a reservation under the name {name}."},{"en":"passport","tr":"pasaport","ex":"Can I see your passport, please?"},{"en":"breakfast","tr":"kahvaltı","ex":"Breakfast is in the morning."},{"en":"included","tr":"dahil","ex":"Is breakfast included?"},{"en":"floor","tr":"kat","ex":"Your room is on the fifth floor."}],"grammar":{"title":"To be: I am / Is it...? / It is","tr":"'To be' fiili 'olmak' demektir: I am, you are, it is. Soru sorarken fiil başa gelir: Is breakfast included? Are you here for work?","examples":["I am here for a business conference.","Is breakfast included?","Your room is on the fifth floor."]},"questions":[{"q":"Why is the speaker here?","options":["For a holiday","For a business conference","For a family visit"],"a":1},{"q":"How many days is the visit?","options":["Four days","Two days","Ten days"],"a":0},{"q":"Where is the room?","options":["On the first floor","On the third floor","On the fifth floor"],"a":2}],"gaps":[{"s":"I am here for a business ___.","a":"conference","hint":"konferans"},{"s":"I have a ___ under the name {name}.","a":"reservation","hint":"rezervasyon"},{"s":"Can I see your ___, please?","a":"passport","hint":"pasaport"}],"order":[{"a":"I am here for four days."},{"a":"Your room is on the fifth floor."}],"translate":[{"tr":"Bir iş konferansı için buradayım.","en":"I am here for a business conference.","keys":["here for","business conference"]},{"tr":"Kahvaltı dahil mi?","en":"Is breakfast included?","keys":["breakfast","included"]}],"roleplay":{"persona":"Hotel receptionist","personaTr":"Otel resepsiyonisti","scene":"Berlin'de akşam otele giriş yapıyorsun.","turns":[{"ai":"Good evening! Can I help you?","aiTr":"İyi akşamlar! Yardımcı olabilir miyim?","hint":"Good evening. I have a reservation under the name {name}.","keys":["reservation","under the name"]},{"ai":"Thank you. Can I see your passport, please?","aiTr":"Teşekkürler. Pasaportunuzu görebilir miyim, lütfen?","hint":"Yes, here you are.","keys":["here you are","yes"]},{"ai":"Your room is 512. Do you have a question?","aiTr":"Odanız 512. Bir sorunuz var mı?","hint":"Yes. Is breakfast included?","keys":["breakfast","included"]}]}},"ab-02":{"intro":"Berlin'de bir bankadasın ve banka memuruyla basit cümlelerle hesap açıyorsun.","text":[{"who":"Clerk","en":"Hello, how can I help you?","tr":"Merhaba, size nasıl yardımcı olabilirim?"},{"who":"Me","en":"I want to open a bank account, please.","tr":"Bir banka hesabı açmak istiyorum, lütfen."},{"who":"Clerk","en":"Do you have your passport and residence permit?","tr":"Pasaportunuz ve oturma izniniz yanınızda mı?"},{"who":"Me","en":"Yes, and I have my address registration too.","tr":"Evet, adres kayıt belgem de var."},{"who":"Clerk","en":"Good, your debit card comes by post.","tr":"Güzel; banka kartınız postayla gelir."},{"who":"Clerk","en":"Your PIN comes in a different letter.","tr":"Şifreniz ayrı bir mektupla gelir."},{"who":"Me","en":"Is the account free?","tr":"Hesap ücretsiz mi?"},{"who":"Clerk","en":"Yes, if you get €1,000 or more a month.","tr":"Evet, ayda 1.000 avro veya daha fazla para gelirse."}],"vocab":[{"en":"bank account","tr":"banka hesabı","ex":"I want to open a bank account."},{"en":"residence permit","tr":"oturma izni","ex":"Here is my residence permit."},{"en":"debit card","tr":"banka kartı","ex":"Your debit card comes by post."},{"en":"by post","tr":"postayla","ex":"The card comes by post."},{"en":"PIN","tr":"kart şifresi","ex":"Your PIN comes in a different letter."},{"en":"free","tr":"ücretsiz","ex":"Is the account free?"}],"grammar":{"title":"Present simple: it comes, it is","tr":"Genel gerçekleri ve her zaman olan şeyleri present simple ile anlatırız. He/she/it ile fiile -s ekleriz: come → comes.","examples":["Your debit card comes by post.","Your PIN comes in a different letter.","I have my passport."]},"questions":[{"q":"What does the speaker want?","options":["A new phone","A bank account","A flat"],"a":1},{"q":"How does the debit card arrive?","options":["By post","By email","At the bank today"],"a":0},{"q":"When is the account free?","options":["Always","Never","If €1,000 or more comes in a month"],"a":2}],"gaps":[{"s":"I want to open a bank ___, please.","a":"account","hint":"hesap"},{"s":"Your debit card comes by ___.","a":"post","hint":"posta"},{"s":"Do you have your passport and residence ___?","a":"permit","hint":"izin"}],"order":[{"a":"I want to open a bank account."},{"a":"Your PIN comes in a different letter."}],"translate":[{"tr":"Pasaportum ve oturma iznim var.","en":"I have my passport and residence permit.","keys":["passport","residence permit"]},{"tr":"Hesap ücretsiz mi?","en":"Is the account free?","keys":["account","free"]}],"roleplay":{"persona":"Bank clerk","personaTr":"Banka memuru","scene":"Berlin'de bir bankadasın ve hesap açmak istiyorsun. Banka memuru sana sorular soruyor.","turns":[{"ai":"Hello! How can I help you?","aiTr":"Merhaba! Size nasıl yardımcı olabilirim?","hint":"Hello, I want to open a bank account, please.","keys":["open","bank account","account"]},{"ai":"A personal account or a business account?","aiTr":"Kişisel hesap mı, şirket hesabı mı?","hint":"A personal account, please.","keys":["personal","personal account"]},{"ai":"Do you have your passport?","aiTr":"Pasaportunuz yanınızda mı?","hint":"Yes, here is my passport and my residence permit.","keys":["passport","residence permit","here is"]}]}},"ai-03":{"intro":"Bir yatırımcıya prototipini çok basit cümlelerle tanıtıyorsun.","text":[{"en":"Thank you for your time.","tr":"Zamanınız için teşekkür ederim."},{"en":"This is our prototype: a hearing test device with AI.","tr":"Bu bizim prototipimiz: yapay zekâlı bir işitme testi cihazı."},{"en":"This is the third version.","tr":"Bu, üçüncü versiyon."},{"en":"The first version was a laptop and headphones.","tr":"İlk versiyon bir dizüstü bilgisayar ve kulaklıktı."},{"en":"We have test results from 200 people.","tr":"200 kişiden test sonuçlarımız var."},{"en":"The results match an expert in 94% of tests.","tr":"Sonuçlar, testlerin %94'ünde bir uzmanınkiyle eşleşiyor."},{"en":"We need €500,000 to finish certification.","tr":"Sertifikasyonu bitirmek için 500.000 €'ya ihtiyacımız var."},{"en":"Then we can sell in Europe.","tr":"Sonra Avrupa'da satış yapabiliriz."}],"vocab":[{"en":"prototype","tr":"prototip","ex":"This is our prototype."},{"en":"version","tr":"versiyon, sürüm","ex":"This is the third version."},{"en":"laptop","tr":"dizüstü bilgisayar","ex":"The first version was a laptop."},{"en":"results","tr":"sonuçlar","ex":"We have good results."},{"en":"match","tr":"eşleşmek, uyuşmak","ex":"The results match an expert."},{"en":"certification","tr":"sertifikasyon","ex":"We need money for certification."}],"grammar":{"title":"To be: is / are / was","tr":"'To be' fiili: şimdiki zaman için am / is / are, geçmiş için was / were kullanılır. Bir şeyi tanıtırken çok işe yarar: This is our prototype.","examples":["This is our prototype.","This is the third version.","The first version was a laptop and headphones."]},"questions":[{"q":"Which version is the prototype?","options":["The first","The second","The third"],"a":2},{"q":"What was the first version?","options":["A laptop and headphones","A phone","A big machine"],"a":0},{"q":"How much money do they need?","options":["€50,000","€500,000","€5 million"],"a":1}],"gaps":[{"s":"This is the third ___.","a":"version","hint":"versiyon"},{"s":"The first version was a ___ and headphones.","a":"laptop","hint":"dizüstü bilgisayar"},{"s":"The results ___ an expert in 94% of tests.","a":"match","hint":"eşleşmek"}],"order":[{"a":"This is the third version."},{"a":"We have test results from 200 people."}],"translate":[{"tr":"Bu bizim prototipimiz.","en":"This is our prototype.","keys":["our prototype"]},{"tr":"500.000 €'ya ihtiyacımız var.","en":"We need €500,000.","keys":["need","500"]}],"roleplay":{"persona":"Investor","personaTr":"Yatırımcı","scene":"Londra'da bir sağlık teknolojisi yatırımcısı prototipini görmek istiyor.","turns":[{"ai":"Hello. What is this?","aiTr":"Merhaba. Bu ne?","hint":"This is our prototype. It is a hearing test device with AI.","keys":["prototype","hearing test"]},{"ai":"Is it the first version?","aiTr":"Bu ilk versiyon mu?","hint":"No, it is the third version.","keys":["third","version"]},{"ai":"How much money do you need?","aiTr":"Ne kadar paraya ihtiyacınız var?","hint":"We need €500,000 to finish certification.","keys":["500","certification"]}]}},"in-01":{"intro":"Yatırımcılara girişimini çok kısa ve basit cümlelerle tanıtıyorsun.","text":[{"who":"Me","en":"Hello everyone, I am {name}, the founder of AIHEAR.","tr":"Herkese merhaba, ben {name}, AIHEAR'ın kurucusuyum."},{"who":"Me","en":"One in five people has hearing loss.","tr":"Her beş kişiden biri işitme kaybı yaşıyor."},{"who":"Me","en":"But there are not enough hearing experts.","tr":"Ama yeterince işitme uzmanı yok."},{"who":"Me","en":"Our device tests hearing without an expert.","tr":"Cihazımız işitmeyi uzman olmadan test ediyor."},{"who":"Me","en":"The test takes less than ten minutes.","tr":"Test on dakikadan kısa sürüyor."},{"who":"Me","en":"We have five paying customers and a team of six.","tr":"Beş ödeme yapan müşterimiz ve altı kişilik bir ekibimiz var."},{"who":"Me","en":"We need 500,000 euros to sell in Europe.","tr":"Avrupa'da satış yapmak için 500.000 euroya ihtiyacımız var."},{"who":"Me","en":"Thank you for listening.","tr":"Dinlediğiniz için teşekkürler."}],"vocab":[{"en":"founder","tr":"kurucu","ex":"I am the founder of AIHEAR."},{"en":"hearing loss","tr":"işitme kaybı","ex":"One in five people has hearing loss."},{"en":"expert","tr":"uzman","ex":"There are not enough experts."},{"en":"paying customer","tr":"ödeme yapan müşteri","ex":"We have five paying customers."},{"en":"team","tr":"ekip","ex":"We have a team of six."},{"en":"less than","tr":"-den az","ex":"The test takes less than ten minutes."}],"grammar":{"title":"Have / has","tr":"'Have' sahip olmayı anlatır. I, you, we, they ile 'have'; he, she, it ile 'has' kullanılır. 'One in five people' tekil sayıldığı için 'has' alır.","examples":["We have five paying customers.","One in five people has hearing loss.","We have a team of six."]},"questions":[{"q":"Who is speaking?","options":["A doctor","The founder of AIHEAR","An investor"],"a":1},{"q":"How long does the test take?","options":["Less than ten minutes","One hour","One day"],"a":0},{"q":"How much money do they need?","options":["50,000 euros","5 million euros","500,000 euros"],"a":2}],"gaps":[{"s":"I am the ___ of AIHEAR.","a":"founder","hint":"kurucu"},{"s":"One in five people has hearing ___.","a":"loss","hint":"kayıp"},{"s":"We have five paying ___.","a":"customers","hint":"müşteriler"}],"order":[{"a":"Our device tests hearing without an expert."},{"a":"The test takes less than ten minutes."}],"translate":[{"tr":"Ben AIHEAR'ın kurucusuyum.","en":"I am the founder of AIHEAR.","keys":["founder","AIHEAR"]},{"tr":"Altı kişilik bir ekibimiz var.","en":"We have a team of six.","keys":["team of six"]}],"roleplay":{"persona":"Investor at a demo day","personaTr":"Demo günü yatırımcısı","scene":"Sunumun bitti. Yatırımcı kısa sorular soruyor.","turns":[{"ai":"Hi! What is your name and your company?","aiTr":"Merhaba! Adınız ve şirketiniz ne?","hint":"My name is {name}, and I am the founder of AIHEAR.","keys":["founder","AIHEAR","my name is"]},{"ai":"What does your device do?","aiTr":"Cihazınız ne yapıyor?","hint":"It tests hearing without an expert, in less than ten minutes.","keys":["tests hearing","without an expert","ten minutes"]},{"ai":"How much money do you need?","aiTr":"Ne kadar paraya ihtiyacınız var?","hint":"We need 500,000 euros.","keys":["500,000","euros"]}]}},"st-03":{"intro":"İki seçenek arasında nasıl karar verdiğini çok basit cümlelerle anlatıyorsun.","text":[{"en":"This is a difficult decision for our startup.","tr":"Bu, girişimimiz için zor bir karar."},{"en":"We have two options.","tr":"İki seçeneğimiz var."},{"en":"Option A: we sell our device to hospitals.","tr":"A seçeneği: cihazımızı hastanelere biz satıyoruz."},{"en":"Option B: a distributor sells it for us.","tr":"B seçeneği: bir distribütör onu bizim için satıyor."},{"en":"Option A is slow, but we get more money.","tr":"A seçeneği yavaş ama daha çok para kazanıyoruz."},{"en":"Option B is fast, but we get less money.","tr":"B seçeneği hızlı ama daha az para kazanıyoruz."},{"en":"Our choice is option B, because time is very important.","tr":"Seçimimiz B seçeneği, çünkü zaman çok önemli."},{"en":"It is not easy, but I think it is right.","tr":"Kolay değil ama bence doğru."}],"vocab":[{"en":"decision","tr":"karar","ex":"This is a difficult decision.","def":"a choice you make after thinking"},{"en":"option","tr":"seçenek","ex":"We have two options.","def":"one of the things you can choose"},{"en":"sell","tr":"satmak","ex":"We sell our device to hospitals.","def":"to give something for money"},{"en":"distributor","tr":"distribütör, dağıtıcı","ex":"A distributor sells it for us.","def":"a company that sells other companies' products"},{"en":"fast","tr":"hızlı","ex":"Option B is fast.","def":"quick, not slow"},{"en":"choice","tr":"seçim","ex":"Our choice is option B.","def":"the thing you choose"}],"grammar":{"title":"To be + adjective: Option A is slow","tr":"Bir şeyi tarif etmek için 'is/are' + sıfat kullanırız: 'Option B is fast.' Olumsuz cümlede 'not' ekleriz: 'It is not easy.'","examples":["Option A is slow.","Option B is fast.","It is not easy."]},"questions":[{"q":"What is option A?","options":["We sell the device to hospitals","A distributor sells it","We close the company"],"a":0},{"q":"Which option is fast?","options":["Option A","Option B","Both options"],"a":1},{"q":"What is their choice?","options":["Option A","No option","Option B"],"a":2}],"gaps":[{"s":"We have two ___.","a":"options","hint":"seçenekler"},{"s":"Option B: a ___ sells it for us.","a":"distributor","hint":"distribütör"},{"s":"Our choice is option B, because time is very ___.","a":"important","hint":"önemli"}],"order":[{"a":"This is a difficult decision for our startup."},{"a":"It is not easy but I think it is right."}],"translate":[{"tr":"İki seçeneğimiz var.","en":"We have two options.","keys":["two options"]},{"tr":"Zaman çok önemli.","en":"Time is very important.","keys":["time","important"]}],"roleplay":{"persona":"Co-founder","personaTr":"Kurucu ortak","scene":"Kurucu ortağın, cihazı kendiniz mi satacaksınız yoksa bir distribütörle mi çalışacaksınız diye soruyor.","turns":[{"ai":"Option A or option B?","aiTr":"A seçeneği mi, B seçeneği mi?","hint":"Option B. A distributor sells it for us.","keys":["option B","distributor"]},{"ai":"Why option B?","aiTr":"Neden B seçeneği?","hint":"Option B is fast, and time is very important.","keys":["fast","time","important"]},{"ai":"But we get less money. Is that OK?","aiTr":"Ama daha az para kazanıyoruz. Bu sorun değil mi?","hint":"It is not easy, but I think it is right.","keys":["right","not easy"]}]}},"te-02":{"intro":"Küçük ekibinin yapay zekâ araçlarıyla nasıl kod yazdığını basit cümlelerle anlatıyorsun.","text":[{"en":"We have three engineers in our team.","tr":"Ekibimizde üç mühendis var."},{"en":"They use AI tools to write code.","tr":"Kod yazmak için yapay zekâ araçları kullanıyorlar."},{"en":"We tell the AI what we want.","tr":"Yapay zekâya ne istediğimizi söylüyoruz."},{"en":"Then the AI writes the first version.","tr":"Sonra yapay zekâ ilk sürümü yazıyor."},{"en":"Our engineers check the code and test it.","tr":"Mühendislerimiz kodu kontrol edip test ediyor."},{"en":"AI is fast, but it can make mistakes.","tr":"Yapay zekâ hızlı ama hata yapabilir."},{"en":"Now a one-week task takes one or two days.","tr":"Artık bir haftalık bir iş bir ya da iki gün sürüyor."},{"en":"It is like having three more engineers.","tr":"Üç mühendisimiz daha varmış gibi."}],"vocab":[{"en":"write code","tr":"kod yazmak","ex":"They use AI tools to write code."},{"en":"engineer","tr":"mühendis","ex":"We have three engineers."},{"en":"first version","tr":"ilk sürüm","ex":"The AI writes the first version."},{"en":"check","tr":"kontrol etmek","ex":"Our engineers check the code."},{"en":"test","tr":"test etmek","ex":"We test the code every day."},{"en":"mistake","tr":"hata","ex":"AI can make mistakes."}],"grammar":{"title":"Present simple: we / they","tr":"Her zaman yaptığımız işler için present simple kullanırız. I, you, we, they ile fiil yalın kalır: we tell, they use, our engineers check.","examples":["They use AI tools to write code.","We tell the AI what we want.","Our engineers check the code."]},"questions":[{"q":"How many engineers are in the team?","options":["Two","Three","Six"],"a":1},{"q":"Who checks the code?","options":["The AI","The customers","The engineers"],"a":2},{"q":"How long does a one-week task take now?","options":["One or two days","Two weeks","One hour"],"a":0}],"gaps":[{"s":"They use AI tools to write ___.","a":"code","hint":"kod"},{"s":"Then the AI writes the first ___.","a":"version","hint":"sürüm"},{"s":"AI is fast, but it can make ___.","a":"mistakes","hint":"hatalar"}],"order":[{"a":"Our engineers check the code and test it."},{"a":"We tell the AI what we want."}],"translate":[{"tr":"Mühendislerimiz kodu kontrol ediyor.","en":"Our engineers check the code.","keys":["engineers","check","code"]},{"tr":"Yapay zekâ hızlı ama hata yapabilir.","en":"AI is fast, but it can make mistakes.","keys":["fast","mistakes"]}],"roleplay":{"persona":"Investor","personaTr":"Yatırımcı","scene":"Bir yatırımcı küçük ekibinin nasıl hızlı çalıştığını soruyor.","turns":[{"ai":"Your team is small. How do you work so fast?","aiTr":"Ekibiniz küçük. Nasıl bu kadar hızlı çalışıyorsunuz?","hint":"We use AI tools to write code.","keys":["AI tools","write code"]},{"ai":"Is the AI code good?","aiTr":"Yapay zekânın yazdığı kod iyi mi?","hint":"Not always. Our engineers check the code and test it.","keys":["check","test","engineers"]},{"ai":"How much time do you save?","aiTr":"Ne kadar zaman kazanıyorsunuz?","hint":"A lot. Now a one-week task takes one or two days.","keys":["one or two days","one-week","a lot"]}]}},"co-02":{"intro":"Konferansta tanıştığın Sarah'ya kısa ve basit bir e-posta yazıyorsun.","text":[{"en":"Subject: Nice to meet you","tr":"Konu: Tanıştığımıza memnun oldum"},{"en":"Hi Sarah,","tr":"Merhaba Sarah,"},{"en":"It was nice to meet you yesterday.","tr":"Dün seninle tanışmak çok güzeldi."},{"en":"Here is a short presentation about our device.","tr":"Cihazımız hakkında kısa bir sunumu ekte bulabilirsin."},{"en":"Can I show the device to your team online?","tr":"Cihazı ekibine çevrimiçi gösterebilir miyim?"},{"en":"Are you free on Tuesday or Wednesday afternoon?","tr":"Salı veya çarşamba öğleden sonra müsait misin?"},{"en":"Please write to me if you have questions.","tr":"Soruların olursa lütfen bana yaz."},{"en":"Best wishes, {name}","tr":"Sevgiler, {name}"}],"vocab":[{"en":"It was nice to meet you.","tr":"Tanışmak güzeldi.","ex":"It was nice to meet you yesterday."},{"en":"presentation","tr":"sunum","ex":"Here is a short presentation."},{"en":"online","tr":"çevrimiçi","ex":"Can I show the device online?"},{"en":"be free","tr":"müsait olmak","ex":"Are you free on Tuesday?"},{"en":"have questions","tr":"sorusu olmak","ex":"Please write to me if you have questions."},{"en":"Best wishes","tr":"Sevgiler, iyi dileklerimle","ex":"Best wishes, Sarah"}],"grammar":{"title":"Can: asking and offering","tr":"'Can I...?' ile bir şey yapmayı teklif eder veya izin isteriz. Soru yaparken 'can' başa gelir: Can I show...?","examples":["Can I show the device to your team?","Can we talk on Tuesday?","You can write to me."]},"questions":[{"q":"Who is the email for?","options":["Emma","Sarah","The team"],"a":1},{"q":"What is in the email?","options":["A short presentation","A contract","A photo"],"a":0},{"q":"Which days are in the email?","options":["Monday or Friday","Saturday or Sunday","Tuesday or Wednesday"],"a":2}],"gaps":[{"s":"It was nice to ___ you yesterday.","a":"meet","hint":"tanışmak"},{"s":"Here is a short ___ about our device.","a":"presentation","hint":"sunum"},{"s":"Are you ___ on Tuesday or Wednesday afternoon?","a":"free","hint":"müsait"}],"order":[{"a":"Can I show the device to your team online?"},{"a":"Are you free on Tuesday or Wednesday afternoon?"}],"translate":[{"tr":"Dün seninle tanışmak güzeldi.","en":"It was nice to meet you yesterday.","keys":["nice to meet you","yesterday"]},{"tr":"Soruların olursa lütfen bana yaz.","en":"Please write to me if you have questions.","keys":["write to me","questions"]}],"roleplay":{"persona":"Sarah (by email)","personaTr":"Sarah (e-posta ile)","scene":"Sarah e-postana cevap veriyor. Kısa ve basit cevaplar yaz.","turns":[{"ai":"Hi {name}, thank you for the presentation. When are you free?","aiTr":"Merhaba {name}, sunum için teşekkürler. Ne zaman müsaitsin?","hint":"I am free on Tuesday or Wednesday afternoon.","keys":["Tuesday","Wednesday","afternoon","free"]},{"ai":"Wednesday at 2 pm is good. Who can come from my team?","aiTr":"Çarşamba 14:00 iyi. Ekibimden kim gelebilir?","hint":"Your clinic manager and an audiologist can come.","keys":["clinic manager","audiologist"]},{"ai":"Great, see you on Wednesday!","aiTr":"Harika, çarşamba görüşürüz!","hint":"Thank you, see you on Wednesday. Best wishes, {name}","keys":["thank you","see you","Wednesday"]}]}},"ab-03":{"intro":"Berlin'de doktordan randevu alıyorsun ve sırt ağrını ve uykusuzluğunu basit cümlelerle anlatıyorsun.","text":[{"who":"Receptionist","en":"Dr Hoffmann's practice, how can I help?","tr":"Dr. Hoffmann'ın muayenehanesi, nasıl yardımcı olabilirim?"},{"who":"Me","en":"Hello, I need an appointment with the doctor.","tr":"Merhaba, doktordan randevu almam gerekiyor."},{"who":"Receptionist","en":"Can you come on Thursday at 9:30?","tr":"Perşembe saat 9.30'da gelebilir misiniz?"},{"who":"Receptionist","en":"Please bring your health insurance card.","tr":"Lütfen sağlık sigortası kartınızı getirin."},{"who":"Doctor","en":"What is the problem?","tr":"Sorun nedir?"},{"who":"Me","en":"My back hurts, and I sleep badly.","tr":"Sırtım ağrıyor ve kötü uyuyorum."},{"who":"Me","en":"I work twelve hours a day at my laptop.","tr":"Günde on iki saat dizüstü bilgisayarımın başında çalışıyorum."},{"who":"Doctor","en":"Take this prescription to the pharmacy, and walk every day.","tr":"Bu reçeteyi eczaneye götürün ve her gün yürüyün."}],"vocab":[{"en":"appointment","tr":"randevu","ex":"I need an appointment with the doctor."},{"en":"health insurance card","tr":"sağlık sigortası kartı","ex":"Please bring your health insurance card."},{"en":"My back hurts.","tr":"Sırtım ağrıyor.","ex":"My back hurts, and I am tired."},{"en":"sleep badly","tr":"kötü uyumak","ex":"I sleep badly at night."},{"en":"prescription","tr":"reçete","ex":"Take this prescription to the pharmacy."},{"en":"pharmacy","tr":"eczane","ex":"The pharmacy is next to the practice."}],"grammar":{"title":"Present simple: my back hurts","tr":"Her gün olan şeyleri ve şu anki durumları present simple ile anlatırız. He/she/it ile fiile -s ekleriz: hurt → hurts.","examples":["My back hurts.","I sleep badly.","I work twelve hours a day."]},"questions":[{"q":"When is the appointment?","options":["Thursday at 9:30","Friday at 9:30","Thursday at 10:30"],"a":0},{"q":"What does the speaker need to bring?","options":["A passport","A health insurance card","A photo"],"a":1},{"q":"Where does the speaker take the prescription?","options":["To the office","To the bank","To the pharmacy"],"a":2}],"gaps":[{"s":"I need an ___ with the doctor.","a":"appointment","hint":"randevu"},{"s":"Please bring your health insurance ___.","a":"card","hint":"kart"},{"s":"Take this prescription to the ___.","a":"pharmacy","hint":"eczane"}],"order":[{"a":"I work twelve hours a day at my laptop."},{"a":"Please bring your health insurance card."}],"translate":[{"tr":"Sırtım ağrıyor.","en":"My back hurts.","keys":["back","hurts"]},{"tr":"Kötü uyuyorum.","en":"I sleep badly.","keys":["sleep badly"]}],"roleplay":{"persona":"Doctor","personaTr":"Doktor","scene":"Berlin'de Dr. Hoffmann'ın muayenehanesindesin. Doktor sana sorular soruyor.","turns":[{"ai":"Hello, what is the problem?","aiTr":"Merhaba, sorun nedir?","hint":"My back hurts, and I sleep badly.","keys":["back","hurts","sleep"]},{"ai":"How many weeks?","aiTr":"Kaç haftadır?","hint":"Three weeks.","keys":["three weeks","three"]},{"ai":"Do you take any medicine?","aiTr":"Herhangi bir ilaç alıyor musunuz?","hint":"Yes, I take ibuprofen sometimes.","keys":["ibuprofen","yes","sometimes"]}]}},"in-02":{"intro":"Şirketinin nasıl para kazandığını basit rakamlarla anlatıyorsun.","text":[{"who":"Me","en":"Investors often ask: how do you make money?","tr":"Yatırımcılar sık sık sorar: Nasıl para kazanıyorsunuz?"},{"who":"Me","en":"We make money in two ways.","tr":"İki yoldan para kazanıyoruz."},{"who":"Me","en":"First, we sell the device for 4,000 euros.","tr":"Birincisi, cihazı 4.000 euroya satıyoruz."},{"who":"Me","en":"It costs us 1,500 euros to make.","tr":"Cihazı üretmek bize 1.500 euroya mal oluyor."},{"who":"Me","en":"Second, each clinic pays 99 euros every month.","tr":"İkincisi, her klinik her ay 99 euro ödüyor."},{"who":"Me","en":"This money comes every month, and investors like that.","tr":"Bu para her ay geliyor ve yatırımcılar bunu seviyor."},{"who":"Me","en":"Our big costs are salaries, certification and marketing.","tr":"Büyük maliyetlerimiz maaşlar, sertifikasyon ve pazarlama."},{"who":"Me","en":"We expect a profit in our third year.","tr":"Üçüncü yılımızda kâr etmeyi bekliyoruz."}],"vocab":[{"en":"make money","tr":"para kazanmak","ex":"How do you make money?"},{"en":"sell","tr":"satmak","ex":"We sell the device for 4,000 euros."},{"en":"cost","tr":"mal olmak; maliyet","ex":"It costs us 1,500 euros to make."},{"en":"every month","tr":"her ay","ex":"Each clinic pays every month."},{"en":"salary","tr":"maaş","ex":"Salaries are a big cost."},{"en":"profit","tr":"kâr","ex":"We expect a profit in our third year."}],"grammar":{"title":"Questions with do / does","tr":"Geniş zamanda soru sormak için I, you, we, they ile 'do', he, she, it ile 'does' kullanılır. Fiil yalın kalır: 'How do you make money?'","examples":["How do you make money?","How much does the device cost?","Does each clinic pay every month?"]},"questions":[{"q":"How much is the device?","options":["4,000 euros","1,500 euros","99 euros"],"a":0},{"q":"How much does a clinic pay every month?","options":["4,000 euros","1,500 euros","99 euros"],"a":2},{"q":"When do they expect a profit?","options":["In year one","In year three","In year ten"],"a":1}],"gaps":[{"s":"We ___ the device for 4,000 euros.","a":"sell","hint":"satıyoruz"},{"s":"Each clinic pays 99 euros every ___.","a":"month","hint":"ay"},{"s":"We expect a ___ in our third year.","a":"profit","hint":"kâr"}],"order":[{"a":"We make money in two ways."},{"a":"We expect a profit in our third year."}],"translate":[{"tr":"Nasıl para kazanıyorsunuz?","en":"How do you make money?","keys":["make money"]},{"tr":"Her klinik her ay ödüyor.","en":"Each clinic pays every month.","keys":["pays","every month"]}],"roleplay":{"persona":"Angel investor","personaTr":"Melek yatırımcı","scene":"Bir yatırımcı nasıl para kazandığınızı soruyor. Kısa cevaplar ver.","turns":[{"ai":"How do you make money?","aiTr":"Nasıl para kazanıyorsunuz?","hint":"We sell the device, and each clinic pays every month.","keys":["sell the device","every month","pays"]},{"ai":"How much is the device?","aiTr":"Cihaz ne kadar?","hint":"It is 4,000 euros.","keys":["4,000","euros"]},{"ai":"When do you expect a profit?","aiTr":"Ne zaman kâr bekliyorsunuz?","hint":"In our third year.","keys":["third year","three"]}]}},"ai-04":{"intro":"Tıbbi bir cihazı Avrupa'da satmak için neye ihtiyacın olduğunu basit cümlelerle anlatıyorsun.","text":[{"en":"We make a medical device for hearing tests.","tr":"İşitme testleri için tıbbi bir cihaz yapıyoruz."},{"en":"In Europe, a medical device needs a CE mark.","tr":"Avrupa'da tıbbi bir cihazın CE işaretine ihtiyacı var."},{"en":"Without the CE mark, we cannot sell it there.","tr":"CE işareti olmadan onu orada satamayız."},{"en":"Our device has a medium level of risk.","tr":"Cihazımızın risk düzeyi orta."},{"en":"We must show that it is safe and works.","tr":"Güvenli olduğunu ve çalıştığını göstermemiz gerekiyor."},{"en":"Our results match an expert's results in 94% of tests.","tr":"Testlerin %94'ünde sonuçlarımız bir uzmanın sonuçlarıyla aynı."},{"en":"The process is slow, and we need many documents.","tr":"Süreç yavaş ve çok sayıda belgeye ihtiyacımız var."},{"en":"We want to finish by the end of next year.","tr":"Gelecek yılın sonuna kadar bitirmek istiyoruz."}],"vocab":[{"en":"medical device","tr":"tıbbi cihaz","ex":"Our audiometer is a medical device."},{"en":"sell","tr":"satmak","ex":"We cannot sell the device without the CE mark."},{"en":"risk","tr":"risk","ex":"The device has a medium level of risk."},{"en":"safe","tr":"güvenli","ex":"The test is safe for patients."},{"en":"result","tr":"sonuç","ex":"Our results are very good."},{"en":"document","tr":"belge","ex":"We need many documents."}],"grammar":{"title":"can / cannot","tr":"'can' bir şeyi yapabildiğimizi, 'cannot' yapamadığımızı söyler. Arkasından fiil yalın gelir: can sell, cannot sell. Soru için 'can' başa gelir.","examples":["We cannot sell it in Europe.","We can show that it is safe.","Can you sell it today?"]},"questions":[{"q":"What does a medical device need in Europe?","options":["A CE mark","A big office","A new name"],"a":0},{"q":"What level of risk does the device have?","options":["High","Low","Medium"],"a":2},{"q":"When do they want to finish?","options":["This month","By the end of next year","In ten years"],"a":1}],"gaps":[{"s":"In Europe, a medical device needs a CE ___.","a":"mark","hint":"işaret"},{"s":"We must show that it is ___ and works.","a":"safe","hint":"güvenli"},{"s":"The process is slow, and we need many ___.","a":"documents","hint":"belgeler"}],"order":[{"a":"We make a medical device for hearing tests."},{"a":"Our device has a medium level of risk."}],"translate":[{"tr":"Cihaz güvenli.","en":"The device is safe.","keys":["device","safe"]},{"tr":"Onu Avrupa'da satamayız.","en":"We cannot sell it in Europe.","keys":["cannot sell","Europe"]}],"roleplay":{"persona":"Investor","personaTr":"Yatırımcı","scene":"Bir yatırımcı CE işaretini ve zaman planını soruyor.","turns":[{"ai":"Can you sell your device in Europe now?","aiTr":"Cihazınızı şu anda Avrupa'da satabilir misiniz?","hint":"Not yet. We need a CE mark first.","keys":["CE mark","not yet","need"]},{"ai":"Is the device safe?","aiTr":"Cihaz güvenli mi?","hint":"Yes, it is safe. Our results match an expert's results in 94% of tests.","keys":["safe","94","results"]},{"ai":"When can you finish?","aiTr":"Ne zaman bitirebilirsiniz?","hint":"We want to finish by the end of next year.","keys":["next year","end of","finish"]}]}},"fu-01":{"intro":"Bir sağlık teknolojisi konferansında paneldesin. Bir doktor, yapay zekânın doktorların yerini alıp almayacağını soruyor.","text":[{"who":"Dr. Weber","en":"Will AI take my job as a doctor?","tr":"Yapay zekâ doktorluk işimi elimden alacak mı?"},{"who":"Me","en":"No, AI can help doctors, but the doctor decides.","tr":"Hayır, yapay zekâ doktorlara yardım edebilir ama kararı doktor verir."},{"who":"Me","en":"AI is fast, and it is never tired.","tr":"Yapay zekâ hızlıdır ve hiç yorulmaz."},{"who":"Me","en":"But AI can make mistakes too.","tr":"Ama yapay zekâ da hata yapabilir."},{"who":"Me","en":"It needs good data to work well.","tr":"İyi çalışmak için iyi veriye ihtiyacı var."},{"who":"Me","en":"Patients trust people, not machines.","tr":"Hastalar makinelere değil, insanlara güvenir."},{"who":"Me","en":"Our device can do a hearing test without an expert.","tr":"Cihazımız bir uzman olmadan işitme testi yapabilir."},{"who":"Me","en":"Then the audiologist has time for difficult cases.","tr":"Böylece odyoloğun zor vakalara ayıracak zamanı olur."}],"vocab":[{"en":"decide","tr":"karar vermek","ex":"The doctor decides."},{"en":"fast","tr":"hızlı","ex":"AI is fast."},{"en":"make a mistake","tr":"hata yapmak","ex":"AI can make mistakes too."},{"en":"data","tr":"veri","ex":"It needs good data."},{"en":"trust","tr":"güvenmek","ex":"Patients trust people."},{"en":"difficult case","tr":"zor vaka","ex":"The audiologist has time for difficult cases."}],"grammar":{"title":"can: ability and possibility","tr":"'Can' bir şeyi yapabilmeyi ya da bir olasılığı anlatır: AI can help, AI can make mistakes. 'Can'den sonra fiil yalın gelir, 'to' kullanılmaz.","examples":["AI can help doctors.","AI can make mistakes too.","Our device can do a hearing test without an expert."]},"questions":[{"q":"Who asks the question?","options":["A patient","A doctor","An investor"],"a":1},{"q":"What does AI need to work well?","options":["Good data","A big office","More doctors"],"a":0},{"q":"Who do patients trust?","options":["Machines","Computers","People"],"a":2}],"gaps":[{"s":"AI is fast, and it is never ___.","a":"tired","hint":"yorgun"},{"s":"It needs good ___ to work well.","a":"data","hint":"veri"},{"s":"Patients ___ people, not machines.","a":"trust","hint":"güvenmek"}],"order":[{"a":"AI can make mistakes too."},{"a":"Patients trust people not machines."}],"translate":[{"tr":"Yapay zekâ doktorlara yardım edebilir.","en":"AI can help doctors.","keys":["help doctors"]},{"tr":"Kararı doktor verir.","en":"The doctor decides.","keys":["doctor decides"]}],"roleplay":{"persona":"Skeptical doctor","personaTr":"Şüpheci doktor","scene":"Paneldeki şüpheci bir doktor yapay zekâ hakkında sorular soruyor. Kısa ve net cevap ver.","turns":[{"ai":"Will AI take my job?","aiTr":"Yapay zekâ işimi elimden alacak mı?","hint":"No. AI can help you, but you decide.","keys":["help","decide","no"]},{"ai":"But AI can make mistakes, right?","aiTr":"Ama yapay zekâ hata yapabilir, değil mi?","hint":"Yes, it can. That is why the doctor checks the result.","keys":["doctor","checks","yes"]},{"ai":"What does your device do?","aiTr":"Cihazınız ne yapıyor?","hint":"It does a hearing test without an expert. Then you have time for difficult cases.","keys":["hearing test","difficult cases","time"]}]}},"st-04":{"intro":"Bir distribütörle komisyon oranı için çok basit cümlelerle pazarlık yapıyorsun.","text":[{"who":"Partner","en":"We want 25 percent of every sale.","tr":"Her satışın yüzde 25'ini istiyoruz."},{"who":"Me","en":"That is too much for us.","tr":"Bu bizim için çok fazla."},{"who":"Me","en":"We can give you 15 percent.","tr":"Size yüzde 15 verebiliriz."},{"who":"Partner","en":"That is too little for us.","tr":"Bu bizim için çok az."},{"who":"Me","en":"Can we start with 20 percent for one year?","tr":"Bir yıl için yüzde 20 ile başlayabilir miyiz?"},{"who":"Partner","en":"OK, but only we can sell in Germany.","tr":"Tamam, ama Almanya'da sadece biz satabiliriz."},{"who":"Me","en":"Yes, if you sell enough devices.","tr":"Evet, yeterince cihaz satarsanız."},{"who":"Partner","en":"Good, we can sign next week.","tr":"Güzel, gelecek hafta imzalayabiliriz."}],"vocab":[{"en":"percent","tr":"yüzde","ex":"We can give you 15 percent.","def":"a part of 100"},{"en":"sale","tr":"satış","ex":"We want 25 percent of every sale.","def":"the act of selling something"},{"en":"too much","tr":"çok fazla","ex":"That is too much for us.","def":"more than is good or possible"},{"en":"start with","tr":"...ile başlamak","ex":"Can we start with 20 percent?","def":"to begin with something"},{"en":"sell","tr":"satmak","ex":"Only we can sell in Germany.","def":"to give something for money"},{"en":"sign","tr":"imzalamak","ex":"We can sign next week.","def":"to write your name on a paper to agree"}],"grammar":{"title":"Can: offers and questions","tr":"'Can' ile bir şeyi yapabileceğimizi ya da teklif ettiğimizi söyleriz: 'We can give you 15 percent.' Soru sormak için 'can' başa gelir: 'Can we start with 20 percent?'","examples":["We can give you 15 percent.","Can we start with 20 percent for one year?","We can sign next week."]},"questions":[{"q":"What does the partner want first?","options":["15 percent","25 percent","20 percent"],"a":1},{"q":"What number do they start with?","options":["20 percent","15 percent","25 percent"],"a":0},{"q":"When can they sign?","options":["Today","Next month","Next week"],"a":2}],"gaps":[{"s":"That is too ___ for us.","a":"much","hint":"fazla"},{"s":"Can we start with 20 ___ for one year?","a":"percent","hint":"yüzde"},{"s":"Good, we can ___ next week.","a":"sign","hint":"imzalamak"}],"order":[{"a":"Can we start with 20 percent for one year?"},{"a":"That is too much for us."}],"translate":[{"tr":"Bu bizim için çok fazla.","en":"That is too much for us.","keys":["too much"]},{"tr":"Gelecek hafta imzalayabiliriz.","en":"We can sign next week.","keys":["sign","next week"]}],"roleplay":{"persona":"Distributor","personaTr":"Distribütör","scene":"Almanya'da satış yapmak isteyen Hollandalı bir distribütörle komisyon oranı için pazarlık yapıyorsun.","turns":[{"ai":"We want 25 percent. Is that OK?","aiTr":"Yüzde 25 istiyoruz. Uygun mu?","hint":"That is too much for us. We can give you 15 percent.","keys":["too much","15","percent"]},{"ai":"15 is too little. What can you do?","aiTr":"15 çok az. Ne yapabilirsiniz?","hint":"Can we start with 20 percent for one year?","keys":["20","start with","one year"]},{"ai":"OK. And only we sell in Germany?","aiTr":"Tamam. Ve Almanya'da sadece biz mi satıyoruz?","hint":"Yes, if you sell enough devices.","keys":["yes","if you sell","enough"]}]}},"te-03":{"intro":"Cihazındaki bir sorunu ve çözümünü basit cümlelerle anlatıyorsun.","text":[{"who":"Me","en":"We have a problem with our device.","tr":"Cihazımızla ilgili bir sorunumuz var."},{"who":"Me","en":"In some clinics, the test results are wrong.","tr":"Bazı kliniklerde test sonuçları yanlış."},{"who":"Me","en":"In other clinics, the results are fine.","tr":"Diğer kliniklerde sonuçlar sorunsuz."},{"who":"Me","en":"We look at the data from all the devices.","tr":"Tüm cihazlardan gelen verilere bakıyoruz."},{"who":"Me","en":"The problem is only in rooms with old air conditioners.","tr":"Sorun yalnızca eski klimaların olduğu odalarda."},{"who":"Me","en":"They are very noisy, so patients cannot hear high sounds.","tr":"Bu klimalar çok gürültülü, bu yüzden hastalar tiz sesleri duyamıyor."},{"who":"Me","en":"Now the device checks the noise before every test.","tr":"Artık cihaz her testten önce gürültüyü kontrol ediyor."},{"who":"Me","en":"In a noisy room, the device shows a warning.","tr":"Gürültülü bir odada cihaz bir uyarı gösteriyor."}],"vocab":[{"en":"test result","tr":"test sonucu","ex":"The test results are wrong."},{"en":"wrong","tr":"yanlış","ex":"In some clinics, the results are wrong."},{"en":"look at the data","tr":"verilere bakmak","ex":"We look at the data from all the devices."},{"en":"air conditioner","tr":"klima","ex":"The room has an old air conditioner."},{"en":"noisy","tr":"gürültülü","ex":"The room is too noisy."},{"en":"warning","tr":"uyarı","ex":"The device shows a warning."}],"grammar":{"title":"Present simple: it + -s","tr":"Geniş zamanda he, she, it (ve 'the device' gibi tekil isimler) ile fiile -s eklenir: 'The device checks'. 'We' ve 'they' ile -s eklenmez: 'We look'.","examples":["The device checks the noise.","The device shows a warning.","We look at the data."]},"questions":[{"q":"Where are the results wrong?","options":["In all clinics","In some clinics","In no clinics"],"a":1},{"q":"What do the problem rooms have?","options":["Old air conditioners","New headphones","Big windows"],"a":0},{"q":"What does the device do now?","options":["It stops all tests","It calls a doctor","It checks the noise before the test"],"a":2}],"gaps":[{"s":"In some clinics, the test results are ___.","a":"wrong","hint":"yanlış"},{"s":"The problem is only in rooms with old ___.","a":"air conditioners","hint":"klimalar"},{"s":"In a ___ room, the device shows a warning.","a":"noisy","hint":"gürültülü"}],"order":[{"a":"We look at the data from all the devices."},{"a":"Now the device checks the noise before every test."}],"translate":[{"tr":"Oda fazla gürültülü.","en":"The room is too noisy.","keys":["room","too noisy"]},{"tr":"Sonuçlar yanlış.","en":"The results are wrong.","keys":["results","wrong"]}],"roleplay":{"persona":"Clinic manager","personaTr":"Klinik müdürü","scene":"Bir klinik müdürü bazı kliniklerdeki yanlış sonuçları soruyor. Kısa ve basit cevaplar ver.","turns":[{"ai":"Hello. Some clinics have wrong results. Why?","aiTr":"Merhaba. Bazı kliniklerde sonuçlar yanlış. Neden?","hint":"The rooms have old air conditioners. They are very noisy.","keys":["air conditioners","noisy","noise"]},{"ai":"What can you do?","aiTr":"Ne yapabilirsiniz?","hint":"Now the device checks the noise. If the room is too noisy, it shows a warning.","keys":["checks the noise","warning","too noisy"]},{"ai":"Is the problem in every clinic?","aiTr":"Sorun her klinikte var mı?","hint":"No, only in some clinics. In other clinics, the results are fine.","keys":["some clinics","fine","only"]}]}},"sc-01":{"intro":"Klinik çalışmanı çok basit cümlelerle anlatıyorsun: kim, kaç kişi, sonuç ne?","text":[{"en":"Our device must work like a hearing expert.","tr":"Cihazımız bir işitme uzmanı gibi çalışmalı."},{"en":"So we do a study in two university hospitals.","tr":"Bu yüzden iki üniversite hastanesinde bir çalışma yapıyoruz."},{"en":"There are 200 people in the study.","tr":"Çalışmada 200 kişi var."},{"en":"Each person does a test with our device.","tr":"Her kişi cihazımızla bir test yapıyor."},{"en":"On the same day, an audiologist tests them too.","tr":"Aynı gün bir odyolog da onları test ediyor."},{"en":"The audiologist does not see our result.","tr":"Odyolog bizim sonucumuzu görmüyor."},{"en":"The results are the same in 94 percent of cases.","tr":"Sonuçlar vakaların yüzde 94'ünde aynı."},{"en":"The study is now in a medical journal.","tr":"Çalışma artık bir tıp dergisinde."}],"vocab":[{"en":"study","tr":"çalışma, araştırma","ex":"There are 200 people in the study."},{"en":"hospital","tr":"hastane","ex":"We work with two university hospitals."},{"en":"audiologist","tr":"odyolog (işitme uzmanı)","ex":"An audiologist tests the same person."},{"en":"result","tr":"sonuç","ex":"The audiologist does not see our result."},{"en":"the same","tr":"aynı","ex":"The results are the same."},{"en":"journal","tr":"dergi (bilimsel)","ex":"The study is in a medical journal."}],"grammar":{"title":"Present simple: does / does not","tr":"Geniş zamanda he/she/it ile fiile -s eklenir (does, tests, sees). Olumsuz cümlede 'does not' + fiilin yalın hali gelir.","examples":["Each person does a test with our device.","The audiologist does not see our result.","Our device works like an expert."]},"questions":[{"q":"How many hospitals are in the study?","options":["One","Two","Three"],"a":1},{"q":"How many people are in the study?","options":["200","20","2,000"],"a":0},{"q":"Where is the study now?","options":["On TV","In a newspaper","In a medical journal"],"a":2}],"gaps":[{"s":"There are 200 people in the ___.","a":"study","hint":"çalışma"},{"s":"The audiologist does not see our ___.","a":"result","hint":"sonuç"},{"s":"The results are the ___ in 94 percent of cases.","a":"same","hint":"aynı"}],"order":[{"a":"The audiologist does not see our result."},{"a":"The study is now in a medical journal."}],"translate":[{"tr":"Çalışmada 200 kişi var.","en":"There are 200 people in the study.","keys":["200 people","study"]},{"tr":"Sonuçlar yüzde 94 oranında aynı.","en":"The results are the same in 94 percent of cases.","keys":["results","94 percent"]}],"roleplay":{"persona":"Researcher","personaTr":"Araştırmacı","scene":"Bir araştırmacı çalışmanızı soruyor. Kısa cevaplar ver.","turns":[{"ai":"Hello! Tell me about your study. How many people are in it?","aiTr":"Merhaba! Bana çalışmanızı anlatın. Kaç kişi var?","hint":"There are 200 people in our study.","keys":["200","people"]},{"ai":"What do they do?","aiTr":"Ne yapıyorlar?","hint":"Each person does a test with our device and a test with an audiologist.","keys":["test","device","audiologist"]},{"ai":"And what are the results?","aiTr":"Peki sonuçlar ne?","hint":"The results are the same in 94 percent of cases.","keys":["94 percent","same"]}]}},"ab-04":{"intro":"Merdivende üst kattaki komşunla, pazartesi de kahve makinesinin başında iş arkadaşınla kısa ve kibar bir sohbet ediyorsun.","text":[{"who":"Lena","en":"Hi, I'm Lena from upstairs.","tr":"Merhaba, ben Lena, üst kattan."},{"who":"Me","en":"Nice to meet you, I'm {name}.","tr":"Tanıştığımıza memnun oldum, ben {name}."},{"who":"Lena","en":"It is sunny today, but it is cold.","tr":"Bugün hava güneşli ama soğuk."},{"who":"Lena","en":"Where are you from, and what do you do?","tr":"Nerelisin ve ne iş yapıyorsun?"},{"who":"Me","en":"I am from Istanbul, and I run a startup.","tr":"İstanbulluyum ve bir girişimim var."},{"who":"Lena","en":"There is a barbecue in the courtyard on Sunday.","tr":"Pazar günü avluda mangal var."},{"who":"Tom","en":"Good morning, how was your weekend?","tr":"Günaydın, hafta sonun nasıldı?"},{"who":"Me","en":"It was great, thanks, and I met my neighbours.","tr":"Harikaydı, teşekkürler; komşularımla tanıştım."}],"vocab":[{"en":"neighbour","tr":"komşu","ex":"Lena is my neighbour."},{"en":"upstairs","tr":"üst katta","ex":"Lena lives upstairs."},{"en":"sunny","tr":"güneşli","ex":"It is sunny today."},{"en":"Where are you from?","tr":"Nerelisin?","ex":"Where are you from, Lena?"},{"en":"barbecue","tr":"mangal (partisi)","ex":"There is a barbecue on Sunday."},{"en":"weekend","tr":"hafta sonu","ex":"How was your weekend?"}],"grammar":{"title":"Simple questions: Where…? What…? How…?","tr":"Soru kelimesi (where, what, how) en başa gelir. 'To be' ile: 'Where are you from?' Diğer fiillerle 'do' kullanırız: 'What do you do?'","examples":["Where are you from?","What do you do?","How was your weekend?"]},"questions":[{"q":"Where does Lena live?","options":["Upstairs","In Istanbul","Next to the office"],"a":0},{"q":"What is the weather like?","options":["Rainy and warm","Sunny but cold","Snowy"],"a":1},{"q":"Where is the barbecue?","options":["In a park","At the office","In the courtyard"],"a":2}],"gaps":[{"s":"Hi, I'm Lena from ___.","a":"upstairs","hint":"üst kat"},{"s":"It is ___ today, but it is cold.","a":"sunny","hint":"güneşli"},{"s":"Good morning, how was your ___?","a":"weekend","hint":"hafta sonu"}],"order":[{"a":"There is a barbecue in the courtyard on Sunday."},{"a":"I am from Istanbul."}],"translate":[{"tr":"Tanıştığımıza memnun oldum.","en":"Nice to meet you.","keys":["nice to meet you"]},{"tr":"Hafta sonun nasıldı?","en":"How was your weekend?","keys":["how was","weekend"]}],"roleplay":{"persona":"Neighbour (Lena)","personaTr":"Komşu (Lena)","scene":"Cumartesi sabahı apartman merdiveninde üst kattaki komşun Lena ile karşılaşıyorsun.","turns":[{"ai":"Hi! I'm Lena from upstairs. Are you new here?","aiTr":"Merhaba! Ben Lena, üst kattan. Burada yeni misin?","hint":"Yes, I am new, and I am from Istanbul.","keys":["yes","new","Istanbul"]},{"ai":"Do you like Berlin?","aiTr":"Berlin'i seviyor musun?","hint":"Yes, I love the parks and the bikes.","keys":["love","parks","yes"]},{"ai":"There is a barbecue on Sunday. Can you come?","aiTr":"Pazar günü mangal var. Gelebilir misin?","hint":"Yes, thank you, and I can bring baklava.","keys":["thank you","yes","baklava"]}]}},"co-03":{"intro":"Ortağın fiyatı düşürmek istiyor; sen basit ve nazik cümlelerle karşı çıkıyorsun.","text":[{"who":"Partner","en":"I think our price is too high.","tr":"Bence fiyatımız çok yüksek."},{"who":"Partner","en":"Let's sell the device for 2,000 euros.","tr":"Cihazı 2.000 euroya satalım."},{"who":"Me","en":"I understand, but I am not sure about that.","tr":"Anlıyorum ama bundan emin değilim."},{"who":"Me","en":"The device costs 1,500 euros to make.","tr":"Cihazın üretimi 1.500 euroya mal oluyor."},{"who":"Partner","en":"But customers say it is expensive.","tr":"Ama müşteriler pahalı olduğunu söylüyor."},{"who":"Me","en":"Yes, but we can show them how much they save.","tr":"Evet ama onlara ne kadar tasarruf ettiklerini gösterebiliriz."},{"who":"Partner","en":"Good idea, let's try that for two months.","tr":"İyi fikir, bunu iki ay deneyelim."},{"who":"Me","en":"Great, thank you for listening.","tr":"Harika, dinlediğin için teşekkürler."}],"vocab":[{"en":"price","tr":"fiyat","ex":"I think our price is too high."},{"en":"too high","tr":"çok yüksek","ex":"The price is too high for small clinics."},{"en":"expensive","tr":"pahalı","ex":"Customers say the device is expensive."},{"en":"I am not sure","tr":"emin değilim","ex":"I understand, but I am not sure about that."},{"en":"cost","tr":"mal olmak, tutmak","ex":"The device costs 1,500 euros to make."},{"en":"save money","tr":"para tasarruf etmek","ex":"Our test helps clinics save money."}],"grammar":{"title":"To be: am / is / are","tr":"'To be' fiili 'olmak' anlamındadır: I am, it is, we/they are. Olumsuz için 'not' eklenir: I am not sure.","examples":["Our price is too high.","It is expensive.","I am not sure about that."]},"questions":[{"q":"What price does the partner want?","options":["4,000 euros","2,000 euros","1,500 euros"],"a":1},{"q":"How much does the device cost to make?","options":["1,500 euros","2,000 euros","100 euros"],"a":0},{"q":"What do they try for two months?","options":["A lower price","A new device","Showing customers the savings"],"a":2}],"gaps":[{"s":"I think our ___ is too high.","a":"price","hint":"fiyat"},{"s":"But customers say it is ___.","a":"expensive","hint":"pahalı"},{"s":"I understand, but I am not ___ about that.","a":"sure","hint":"emin"}],"order":[{"a":"I think our price is too high."},{"a":"But customers say it is expensive."}],"translate":[{"tr":"Fiyatımız çok yüksek.","en":"Our price is too high.","keys":["price","too high"]},{"tr":"Bundan emin değilim.","en":"I am not sure about that.","keys":["not sure"]}],"roleplay":{"persona":"Business partner","personaTr":"İş ortağı","scene":"Ortağın cihazı ücretsiz vermek istiyor. Sen nazikçe 'emin değilim' diyorsun.","turns":[{"ai":"Let's give the device away for free.","aiTr":"Cihazı ücretsiz verelim.","hint":"I understand, but I am not sure. The device costs 1,500 euros.","keys":["not sure","costs","understand"]},{"ai":"But customers love free things!","aiTr":"Ama müşteriler ücretsiz şeyleri sever!","hint":"Yes, but we need money to make the device.","keys":["yes but","need money"]},{"ai":"OK. What is your idea?","aiTr":"Tamam. Senin fikrin ne?","hint":"Let's try both ideas with a few clinics for two months.","keys":["try","two months","clinics"]}]}},"in-03":{"intro":"Bir yatırımcı şirketine para yatırmak istiyor; sen şirketinin değeri hakkında konuşuyorsun.","text":[{"who":"Investor","en":"We want to invest 500,000 euros.","tr":"500.000 euro yatırım yapmak istiyoruz."},{"who":"Investor","en":"For this, we want 25 percent of your company.","tr":"Bunun karşılığında şirketinizin yüzde 25'ini istiyoruz."},{"who":"Me","en":"Thank you, but our company is worth more.","tr":"Teşekkürler ama şirketimiz daha değerli."},{"who":"Me","en":"We have a good product and paying customers.","tr":"İyi bir ürünümüz ve ödeme yapan müşterilerimiz var."},{"who":"Me","en":"What about 20 percent?","tr":"Yüzde 20'ye ne dersiniz?"},{"who":"Investor","en":"Yes, but then we want a seat on the board.","tr":"Olur ama o zaman yönetim kurulunda bir koltuk istiyoruz."},{"who":"Me","en":"OK, you can have a seat on the board.","tr":"Tamam, yönetim kurulunda bir koltuk alabilirsiniz."},{"who":"Me","en":"We want an active investor, not just money.","tr":"Sadece para değil, aktif bir yatırımcı istiyoruz."}],"vocab":[{"en":"invest","tr":"yatırım yapmak","ex":"We want to invest 500,000 euros."},{"en":"percent","tr":"yüzde","ex":"They want 25 percent of the company."},{"en":"be worth more","tr":"daha değerli olmak","ex":"Our company is worth more."},{"en":"paying customer","tr":"ödeme yapan müşteri","ex":"We have five paying customers."},{"en":"What about...?","tr":"...'e ne dersiniz?","ex":"What about 20 percent?"},{"en":"a seat on the board","tr":"yönetim kurulunda koltuk","ex":"The investor wants a seat on the board."}],"grammar":{"title":"want / want to","tr":"Bir şey istediğimizde 'want + isim' kullanırız. Bir eylem yapmak istediğimizde 'want to + fiil' kullanırız.","examples":["We want to invest 500,000 euros.","We want a seat on the board.","We want an active investor."]},"questions":[{"q":"How much money does the investor want to invest?","options":["250,000 euros","500,000 euros","5 million euros"],"a":1},{"q":"What percent do they agree on?","options":["10 percent","25 percent","20 percent"],"a":2},{"q":"What does the investor want at the end?","options":["A seat on the board","A new office","A new product"],"a":0}],"gaps":[{"s":"We want to ___ 500,000 euros.","a":"invest","hint":"yatırım yapmak"},{"s":"Our company is ___ more.","a":"worth","hint":"değerinde"},{"s":"We want a seat on the ___.","a":"board","hint":"yönetim kurulu"}],"order":[{"a":"We have a good product and paying customers."},{"a":"You can have a seat on the board."}],"translate":[{"tr":"Şirketimiz daha değerli.","en":"Our company is worth more.","keys":["worth more"]},{"tr":"Yüzde 20'ye ne dersiniz?","en":"What about 20 percent?","keys":["what about","20 percent"]}],"roleplay":{"persona":"Investor","personaTr":"Yatırımcı","scene":"Bir yatırımcı şirketine para yatırmak istiyor. Kısa ve net cevaplar ver.","turns":[{"ai":"We want to invest 500,000 euros for 25 percent.","aiTr":"Yüzde 25 karşılığında 500.000 euro yatırmak istiyoruz.","hint":"Thank you, but our company is worth more.","keys":["worth more","thank you","company"]},{"ai":"Why is your company worth more?","aiTr":"Şirketiniz neden daha değerli?","hint":"We have a good product and paying customers.","keys":["product","paying customers","customers"]},{"ai":"OK, 20 percent, but we want a seat on the board.","aiTr":"Tamam, yüzde 20, ama yönetim kurulunda bir koltuk istiyoruz.","hint":"That is fine. We want an active investor, not just money.","keys":["fine","active investor","board"]}]}},"ai-05":{"intro":"Bir hastane alıcısına fiyatı, garantiyi ve ücretsiz denemeyi basitçe anlatıyorsun.","text":[{"who":"Buyer","en":"How much is your audiometer?","tr":"Odyometreniz ne kadar?"},{"who":"Me","en":"The device is 4,000 euros.","tr":"Cihaz 4.000 euro."},{"who":"Me","en":"The software is 99 euros a month.","tr":"Yazılım ayda 99 euro."},{"who":"Buyer","en":"That is more than a normal audiometer.","tr":"Bu, normal bir odyometreden daha fazla."},{"who":"Me","en":"Yes, but you don't need an expert for every test.","tr":"Evet ama her test için bir uzmana ihtiyacınız yok."},{"who":"Me","en":"There is also a two-year warranty.","tr":"Ayrıca iki yıl garanti var."},{"who":"Buyer","en":"Can we try it first?","tr":"Önce deneyebilir miyiz?"},{"who":"Me","en":"Yes, you can try it for free for one month.","tr":"Evet, bir ay boyunca ücretsiz deneyebilirsiniz."}],"vocab":[{"en":"How much is …?","tr":"… ne kadar?","ex":"How much is the device?"},{"en":"a month","tr":"ayda, aylık","ex":"The software is 99 euros a month."},{"en":"expert","tr":"uzman","ex":"You don't need an expert for every test."},{"en":"warranty","tr":"garanti","ex":"There is a two-year warranty."},{"en":"try","tr":"denemek","ex":"Can we try it first?"},{"en":"for free","tr":"ücretsiz","ex":"You can try it for free."}],"grammar":{"title":"can: asking and saying yes","tr":"'Can' ile izin isteriz ve bir şeyin mümkün olduğunu söyleriz. Soru: Can + özne + fiil? Cevap: Yes, you can.","examples":["Can we try it first?","Yes, you can try it for free.","Can you train our staff?"]},"questions":[{"q":"How much is the device?","options":["400 euros","4,000 euros","99 euros"],"a":1},{"q":"How long is the warranty?","options":["Two years","One year","One month"],"a":0},{"q":"How long is the free trial?","options":["One week","One year","One month"],"a":2}],"gaps":[{"s":"The software is 99 euros a ___.","a":"month","hint":"ay"},{"s":"You don't need an ___ for every test.","a":"expert","hint":"uzman"},{"s":"There is also a two-year ___.","a":"warranty","hint":"garanti"}],"order":[{"a":"The software is 99 euros a month."},{"a":"Can we try it first?"}],"translate":[{"tr":"Cihaz 4.000 euro.","en":"The device is 4,000 euros.","keys":["device","4,000 euros"]},{"tr":"Önce deneyebilir miyiz?","en":"Can we try it first?","keys":["can we try","first"]}],"roleplay":{"persona":"Hospital buyer","personaTr":"Hastane satın alma yöneticisi","scene":"Bir hastanenin satın alma yöneticisi fiyatı ve denemeyi soruyor.","turns":[{"ai":"How much is the device?","aiTr":"Cihaz ne kadar?","hint":"The device is 4,000 euros. The software is 99 euros a month.","keys":["4,000","euros","a month"]},{"ai":"That is expensive.","aiTr":"Bu pahalı.","hint":"Yes, but you don't need an expert for every test.","keys":["expert","every test"]},{"ai":"Can we try it first?","aiTr":"Önce deneyebilir miyiz?","hint":"Yes, you can try it for free for one month.","keys":["free","one month","try"]}]}},"te-04":{"intro":"Yapay zekâ nerede çalışmalı: bulutta mı, cihazda mı? Basit bir seçim yapıyorsun.","text":[{"who":"Engineer","en":"We have two options: the cloud or the device.","tr":"İki seçeneğimiz var: bulut ya da cihaz."},{"who":"Engineer","en":"The cloud is very powerful and easy to update.","tr":"Bulut çok güçlü ve güncellemesi kolay."},{"who":"Engineer","en":"But the cloud does not work without the internet.","tr":"Ama bulut internet olmadan çalışmıyor."},{"who":"Engineer","en":"Some hospitals do not let patient data leave the building.","tr":"Bazı hastaneler hasta verisinin binadan çıkmasına izin vermiyor."},{"who":"Me","en":"What about the device?","tr":"Peki ya cihaz?"},{"who":"Engineer","en":"The device works offline and keeps data private.","tr":"Cihaz internetsiz çalışıyor ve verileri gizli tutuyor."},{"who":"Engineer","en":"But the hardware costs more.","tr":"Ama donanım daha pahalı."},{"who":"Me","en":"Privacy is important for us, so we choose the device.","tr":"Gizlilik bizim için önemli, bu yüzden cihazı seçiyoruz."}],"vocab":[{"en":"option","tr":"seçenek","ex":"We have two options."},{"en":"the cloud","tr":"bulut","ex":"The AI can run in the cloud."},{"en":"patient data","tr":"hasta verisi","ex":"Patient data stays in the hospital."},{"en":"offline","tr":"internetsiz, çevrimdışı","ex":"The device works offline."},{"en":"keep data private","tr":"verileri gizli tutmak","ex":"The device keeps data private."},{"en":"choose","tr":"seçmek","ex":"We choose the device."}],"grammar":{"title":"Present simple negative: do not / does not","tr":"Geniş zamanın olumsuzunda I, you, we, they ile 'do not', he, she, it ile 'does not' kullanılır. Fiil yalın kalır: 'It does not work'.","examples":["Some hospitals do not let patient data leave the building.","The cloud does not work without the internet.","We do not use the cloud."]},"questions":[{"q":"How many options do they have?","options":["One","Two","Three"],"a":1},{"q":"Which option works offline?","options":["The device","The cloud","The internet"],"a":0},{"q":"What do they choose?","options":["The cloud","A new phone","The device"],"a":2}],"gaps":[{"s":"We have two ___: the cloud or the device.","a":"options","hint":"seçenekler"},{"s":"The device works ___.","a":"offline","hint":"internetsiz"},{"s":"Privacy is important for us, so we ___ the device.","a":"choose","hint":"seçiyoruz"}],"order":[{"a":"The cloud is very powerful and easy to update."},{"a":"The device works offline and keeps data private."}],"translate":[{"tr":"Gizlilik önemli.","en":"Privacy is important.","keys":["privacy","important"]},{"tr":"Bulut çok güçlü.","en":"The cloud is very powerful.","keys":["cloud","powerful"]}],"roleplay":{"persona":"Hospital IT manager","personaTr":"Hastane bilgi işlem müdürü","scene":"Bir hastanenin bilgi işlem müdürü hasta verisini soruyor. Kısa ve basit cevap ver.","turns":[{"ai":"Does the device send patient data to the internet?","aiTr":"Cihaz hasta verisini internete gönderiyor mu?","hint":"No. The AI runs on the device, and the data stays private.","keys":["on the device","private","stays"]},{"ai":"Does it need the internet?","aiTr":"İnternet gerekiyor mu?","hint":"No, it works offline.","keys":["offline","works"]},{"ai":"Why not the cloud?","aiTr":"Neden bulut değil?","hint":"Privacy is very important for hospitals.","keys":["privacy","important"]}]}},"li-02":{"intro":"Müşteriler neden hayır der? Üç nedeni basit cümlelerle anlatıyorsun.","text":[{"who":"Me","en":"Sometimes a customer says no to me.","tr":"Bazen bir müşteri bana hayır der."},{"who":"Me","en":"There are three big reasons.","tr":"Bunun üç büyük nedeni var."},{"who":"Me","en":"First, they do not trust me yet.","tr":"Birincisi, bana henüz güvenmiyorlar."},{"who":"Me","en":"Second, they do not understand my product.","tr":"İkincisi, ürünümü anlamıyorlar."},{"who":"Me","en":"Third, the time is not right for them.","tr":"Üçüncüsü, zaman onlar için uygun değil."},{"who":"Me","en":"I answer emails fast, and my words are simple.","tr":"E-postalara hızlı cevap veriyorum ve kelimelerim basit."},{"who":"Me","en":"A no today is often a not yet.","tr":"Bugünkü bir 'hayır' çoğu zaman 'henüz değil' demektir."},{"who":"Me","en":"I wait three months, and then I ask again.","tr":"Üç ay bekliyorum, sonra tekrar soruyorum."}],"vocab":[{"en":"say no","tr":"hayır demek","ex":"Sometimes a customer says no."},{"en":"reason","tr":"neden, sebep","ex":"There are three big reasons."},{"en":"trust","tr":"güvenmek","ex":"They do not trust me yet."},{"en":"understand","tr":"anlamak","ex":"They do not understand my product."},{"en":"not yet","tr":"henüz değil","ex":"A no today is often a not yet."},{"en":"ask again","tr":"tekrar sormak","ex":"I wait, and then I ask again."}],"grammar":{"title":"Present simple: do not","tr":"Olumsuz cümle kurmak için 'do not' (kısaca don't) + fiil kullanılır: I/you/we/they do not trust. He/she/it ile 'does not' kullanılır.","examples":["They do not trust me yet.","They do not understand my product.","The customer does not say yes."]},"questions":[{"q":"How many big reasons are there?","options":["Two","Three","Five"],"a":1},{"q":"What does the speaker do after three months?","options":["Asks again","Stops","Sells the company"],"a":0},{"q":"How are the speaker's words?","options":["Long","Difficult","Simple"],"a":2}],"gaps":[{"s":"There are three big ___.","a":"reasons","hint":"nedenler"},{"s":"They do not ___ me yet.","a":"trust","hint":"güvenmek"},{"s":"I wait three months, and then I ask ___.","a":"again","hint":"tekrar"}],"order":[{"a":"There are three big reasons."},{"a":"A no today is often a not yet."}],"translate":[{"tr":"Bana henüz güvenmiyorlar.","en":"They do not trust me yet.","keys":["trust","yet"]},{"tr":"Üç ay sonra tekrar soruyorum.","en":"I ask again in three months.","keys":["ask again","three months"]}],"roleplay":{"persona":"Clinic owner","personaTr":"Klinik sahibi","scene":"Bir klinik sahibi cihazına 'şimdi değil' diyor. Nedenini öğrenmeye çalışıyorsun.","turns":[{"ai":"Your device is nice, but not now.","aiTr":"Cihazınız güzel ama şimdi değil.","hint":"I understand. What is your big problem today?","keys":["understand","problem","today"]},{"ai":"Our patients wait six weeks for a test.","aiTr":"Hastalarımız bir test için altı hafta bekliyor.","hint":"That is a long time. You can try the device free for one month.","keys":["try","free","one month","long"]},{"ai":"Hmm. I need time to think.","aiTr":"Hmm. Düşünmek için zamana ihtiyacım var.","hint":"No problem. I can write to you next week.","keys":["no problem","next week","write"]}]}},"fu-02":{"intro":"Bir gazeteci seninle sağlık verileri hakkında röportaj yapıyor. Basit cümlelerle cevap veriyorsun.","text":[{"who":"Journalist","en":"Who owns a patient's health data?","tr":"Bir hastanın sağlık verileri kime ait?"},{"who":"Me","en":"The patient owns the data, not the company.","tr":"Verilerin sahibi şirket değil, hastadır."},{"who":"Me","en":"We always ask the patient first.","tr":"Her zaman önce hastaya soruyoruz."},{"who":"Me","en":"For research, we remove names from the data.","tr":"Araştırma için verilerden isimleri siliyoruz."},{"who":"Me","en":"In Europe, there are strict rules for health data.","tr":"Avrupa'da sağlık verileri için sıkı kurallar var."},{"who":"Me","en":"Our AI works on the device.","tr":"Yapay zekâmız cihazın üzerinde çalışıyor."},{"who":"Me","en":"The test data stays in the clinic.","tr":"Test verileri klinikte kalıyor."},{"who":"Me","en":"More data can make AI better, but privacy is important.","tr":"Daha fazla veri yapay zekâyı daha iyi yapabilir, ama gizlilik önemlidir."}],"vocab":[{"en":"health data","tr":"sağlık verisi","ex":"Health data is very personal."},{"en":"own","tr":"sahip olmak","ex":"The patient owns the data."},{"en":"remove","tr":"silmek, çıkarmak","ex":"We remove names from the data."},{"en":"rule","tr":"kural","ex":"There are strict rules in Europe."},{"en":"stay","tr":"kalmak","ex":"The test data stays in the clinic."},{"en":"privacy","tr":"gizlilik","ex":"Privacy is important."}],"grammar":{"title":"Present simple: -s with he, she, it","tr":"Present simple'da he, she, it ve tekil isimlerle fiile -s eklenir: the patient owns, the AI works, the data stays.","examples":["The patient owns the data.","Our AI works on the device.","The test data stays in the clinic."]},"questions":[{"q":"Who owns the health data?","options":["The company","The patient","The government"],"a":1},{"q":"Where does the test data stay?","options":["In the clinic","On the internet","In the company office"],"a":0},{"q":"Where are there strict rules for health data?","options":["In Asia","In America","In Europe"],"a":2}],"gaps":[{"s":"The patient ___ the data, not the company.","a":"owns","hint":"sahip olmak"},{"s":"For research, we remove ___ from the data.","a":"names","hint":"isimler"},{"s":"The test data stays in the ___.","a":"clinic","hint":"klinik"}],"order":[{"a":"We always ask the patient first."},{"a":"Our AI works on the device."}],"translate":[{"tr":"Verinin sahibi hastadır.","en":"The patient owns the data.","keys":["patient","owns the data"]},{"tr":"Gizlilik önemlidir.","en":"Privacy is important.","keys":["privacy","important"]}],"roleplay":{"persona":"Journalist","personaTr":"Gazeteci","scene":"Bir gazeteci sağlık verileri hakkında sorular soruyor. Kısa ve net cevap ver.","turns":[{"ai":"Who owns the health data?","aiTr":"Sağlık verileri kime ait?","hint":"The patient owns the data.","keys":["patient","owns"]},{"ai":"Where is the test data?","aiTr":"Test verileri nerede?","hint":"It stays in the clinic. Our AI works on the device.","keys":["clinic","device","stays"]},{"ai":"Is more data good for AI?","aiTr":"Daha fazla veri yapay zekâ için iyi mi?","hint":"Yes, but privacy is important too.","keys":["privacy","important","yes"]}]}},"in-04":{"intro":"Bir yatırımcı zor sorular soruyor; sen sakin ve kısa cevaplar veriyorsun.","text":[{"who":"Investor","en":"Who are your competitors?","tr":"Rakipleriniz kimler?"},{"who":"Me","en":"Big companies make audiometers, but their devices need an expert.","tr":"Büyük şirketler odyometre yapıyor ama onların cihazları bir uzman gerektiriyor."},{"who":"Investor","en":"Can a big company copy you?","tr":"Büyük bir şirket sizi kopyalayabilir mi?"},{"who":"Me","en":"Our AI learns from thousands of real tests.","tr":"Yapay zekâmız binlerce gerçek testten öğreniyor."},{"who":"Me","en":"This data is very hard to get.","tr":"Bu veriyi elde etmek çok zor."},{"who":"Investor","en":"What is your biggest risk?","tr":"En büyük riskiniz ne?"},{"who":"Me","en":"Honestly, our biggest risk is certification.","tr":"Açıkçası en büyük riskimiz sertifikasyon."},{"who":"Me","en":"We started early and we work with a good consultant.","tr":"Erken başladık ve iyi bir danışmanla çalışıyoruz."}],"vocab":[{"en":"competitor","tr":"rakip","ex":"Who are your competitors?"},{"en":"copy","tr":"kopyalamak","ex":"A big company can copy a small one."},{"en":"data","tr":"veri","ex":"Our AI learns from real data."},{"en":"hard to get","tr":"elde etmesi zor","ex":"This data is very hard to get."},{"en":"risk","tr":"risk","ex":"Our biggest risk is certification."},{"en":"consultant","tr":"danışman","ex":"We work with a good consultant."}],"grammar":{"title":"Present simple: facts about a company","tr":"Şirket hakkındaki genel gerçekleri anlatmak için geniş zaman kullanılır. He, she, it ile fiile -s eklenir: it learns, it makes.","examples":["Big companies make audiometers.","Our AI learns from real tests.","We work with a good consultant."]},"questions":[{"q":"What do big companies make?","options":["Apps","Audiometers","Hearing aids"],"a":1},{"q":"What is very hard to get?","options":["The data","The money","The device"],"a":0},{"q":"What is the biggest risk?","options":["The price","The team","Certification"],"a":2}],"gaps":[{"s":"Who are your ___?","a":"competitors","hint":"rakipler"},{"s":"This data is very hard to ___.","a":"get","hint":"elde etmek"},{"s":"Our biggest ___ is certification.","a":"risk","hint":"risk"}],"order":[{"a":"Our AI learns from thousands of real tests."},{"a":"We started early and we work with a good consultant."}],"translate":[{"tr":"Büyük bir şirket sizi kopyalayabilir mi?","en":"Can a big company copy you?","keys":["big company","copy"]},{"tr":"Bu veriyi elde etmek çok zor.","en":"This data is very hard to get.","keys":["data","hard to get"]}],"roleplay":{"persona":"Investor","personaTr":"Yatırımcı","scene":"Bir yatırımcı rakipleri ve riskleri soruyor. Kısa ve sakin cevap ver.","turns":[{"ai":"Who are your competitors?","aiTr":"Rakipleriniz kimler?","hint":"Big companies make audiometers, but their devices need an expert.","keys":["audiometers","expert","big companies"]},{"ai":"Can a big company copy you?","aiTr":"Büyük bir şirket sizi kopyalayabilir mi?","hint":"Our AI learns from real tests. This data is hard to get.","keys":["data","hard to get","real tests"]},{"ai":"What is your biggest risk?","aiTr":"En büyük riskiniz ne?","hint":"Our biggest risk is certification. We started early.","keys":["certification","started early","risk"]}]}},"sc-02":{"intro":"Hibe nedir ve sizin hibeniz ne için? Çok basit cümlelerle anlatıyorsun.","text":[{"en":"Not all startup money comes from investors.","tr":"Girişimlerin parasının hepsi yatırımcılardan gelmez."},{"en":"Some money comes from grants.","tr":"Paranın bir kısmı hibelerden gelir."},{"en":"With a grant, you do not pay the money back.","tr":"Hibede parayı geri ödemezsiniz."},{"en":"We have a European grant for health technology.","tr":"Sağlık teknolojisi için bir Avrupa hibemiz var."},{"en":"It is 250,000 euros.","tr":"Tutarı 250.000 euro."},{"en":"The money is only for research and clinical tests.","tr":"Para sadece araştırma ve klinik testler için."},{"en":"The application is a lot of work.","tr":"Başvuru çok emek istiyor."},{"en":"But grants are a great way to pay for research.","tr":"Ama hibeler araştırmayı finanse etmenin harika bir yolu."}],"vocab":[{"en":"grant","tr":"hibe","ex":"We have a European grant."},{"en":"investor","tr":"yatırımcı","ex":"Not all money comes from investors."},{"en":"pay back","tr":"geri ödemek","ex":"You do not pay a grant back."},{"en":"research","tr":"araştırma","ex":"The money is for research."},{"en":"application","tr":"başvuru","ex":"The application is a lot of work."},{"en":"health technology","tr":"sağlık teknolojisi","ex":"We work in health technology."}],"grammar":{"title":"Present simple: do not / does not","tr":"Geniş zamanda olumsuz cümle için I/you/we/they ile 'do not', he/she/it ile 'does not' kullanılır. Ardından fiilin yalın hali gelir.","examples":["You do not pay the money back.","Not all money comes from investors.","A grant does not cost you shares."]},"questions":[{"q":"How much is the grant?","options":["25,000 euros","250,000 euros","2,500,000 euros"],"a":1},{"q":"What is the money for?","options":["Research and clinical tests","A new office","Salaries"],"a":0},{"q":"Do you pay a grant back?","options":["Yes, after one year","Yes, every month","No"],"a":2}],"gaps":[{"s":"With a ___, you do not pay the money back.","a":"grant","hint":"hibe"},{"s":"The money is only for ___ and clinical tests.","a":"research","hint":"araştırma"},{"s":"The ___ is a lot of work.","a":"application","hint":"başvuru"}],"order":[{"a":"Some money comes from grants."},{"a":"We have a European grant for health technology."}],"translate":[{"tr":"Parayı geri ödemiyorsunuz.","en":"You do not pay the money back.","keys":["pay","back"]},{"tr":"Para sadece araştırma için.","en":"The money is only for research.","keys":["only","research"]}],"roleplay":{"persona":"Grant jury member","personaTr":"Hibe jürisi üyesi","scene":"Hibe jürisinden biri sana basit sorular soruyor.","turns":[{"ai":"Hello. What does your device do?","aiTr":"Merhaba. Cihazınız ne yapıyor?","hint":"Our device tests hearing in under ten minutes.","keys":["tests hearing","ten minutes"]},{"ai":"Who needs it?","aiTr":"Kimin buna ihtiyacı var?","hint":"People in small towns need it. There are not many audiologists.","keys":["small towns","audiologists","people"]},{"ai":"What is the money for?","aiTr":"Para ne için?","hint":"The money is for research and clinical tests.","keys":["research","clinical tests"]}]}},"st-05":{"intro":"Bir doktor cihazın çalışmadığını söylüyor; özür diliyor ve sorunu çözüyorsun.","text":[{"en":"A doctor from a hospital in Izmir calls me.","tr":"İzmir'deki bir hastaneden bir doktor beni arıyor."},{"en":"Our device stops in the middle of a test.","tr":"Cihazımız bir testin ortasında duruyor."},{"en":"She is angry because many patients are waiting.","tr":"Kızgın, çünkü bekleyen çok hasta var."},{"en":"I say sorry and thank her for the call.","tr":"Özür diliyorum ve aradığı için ona teşekkür ediyorum."},{"en":"Then I ask her some questions.","tr":"Sonra ona birkaç soru soruyorum."},{"en":"It is a software problem, not a hardware problem.","tr":"Bu bir yazılım sorunu, donanım sorunu değil."},{"en":"Our engineer sends an update in two hours.","tr":"Mühendisimiz iki saat içinde bir güncelleme gönderiyor."},{"en":"The device works again, and I call the doctor back.","tr":"Cihaz yeniden çalışıyor ve doktoru geri arıyorum."}],"vocab":[{"en":"say sorry","tr":"özür dilemek","ex":"I say sorry to the doctor."},{"en":"in the middle of","tr":"...in ortasında","ex":"The device stops in the middle of a test."},{"en":"software","tr":"yazılım","ex":"It is a software problem."},{"en":"hardware","tr":"donanım","ex":"The hardware is fine."},{"en":"update","tr":"güncelleme","ex":"Our engineer sends an update."},{"en":"call back","tr":"geri aramak","ex":"I call the doctor back."}],"grammar":{"title":"Present simple: telling a story step by step","tr":"Bir olayı adım adım anlatırken present simple kullanabilirsin. he / she / it ile fiile -s eklenir: she calls, it stops.","examples":["The doctor calls me.","The device stops.","I ask some questions."]},"questions":[{"q":"Where is the hospital?","options":["In Ankara","In Izmir","In Istanbul"],"a":1},{"q":"How does the doctor feel?","options":["Happy","Tired","Angry"],"a":2},{"q":"What is the problem?","options":["A software problem","A hardware problem","A battery problem"],"a":0}],"gaps":[{"s":"Our device stops in the ___ of a test.","a":"middle","hint":"ortasında"},{"s":"I say ___ and thank her for the call.","a":"sorry","hint":"özür dilerim"},{"s":"Our engineer sends an ___ in two hours.","a":"update","hint":"güncelleme"}],"order":[{"a":"Then I ask her some questions."},{"a":"Our engineer sends an update in two hours."}],"translate":[{"tr":"Çok özür dilerim.","en":"I am very sorry.","keys":["very sorry"]},{"tr":"Cihaz yeniden çalışıyor.","en":"The device is working again.","keys":["device","working again"]}],"roleplay":{"persona":"Angry doctor","personaTr":"Kızgın doktor","scene":"İzmir'deki bir hastaneden bir doktor arıyor: cihaz bir testin ortasında durdu.","turns":[{"ai":"Your device is not working!","aiTr":"Cihazınız çalışmıyor!","hint":"I am very sorry. Can I ask some questions?","keys":["sorry","questions"]},{"ai":"The screen is black. I have ten patients here.","aiTr":"Ekran siyah. Burada on hastam var.","hint":"It is a software problem. Our engineer can send an update.","keys":["software","update","engineer"]},{"ai":"When can I use it again?","aiTr":"Onu ne zaman tekrar kullanabilirim?","hint":"In two hours. I can call you back.","keys":["two hours","call you back"]}]}},"li-03":{"intro":"Bir kurucu olarak enerjini nasıl koruduğunu basit cümlelerle anlatıyorsun.","text":[{"who":"Me","en":"In my first year, I was always tired.","tr":"İlk yılımda hep yorgundum."},{"who":"Me","en":"A tired brain is a slow brain.","tr":"Yorgun bir beyin yavaş bir beyindir."},{"who":"Me","en":"Now I have three simple rules.","tr":"Şimdi üç basit kuralım var."},{"who":"Me","en":"First, I sleep at least seven hours.","tr":"Birincisi, en az yedi saat uyuyorum."},{"who":"Me","en":"I do not read emails after ten at night.","tr":"Gece ondan sonra e-posta okumuyorum."},{"who":"Me","en":"Second, I do my most important work in the morning.","tr":"İkincisi, en önemli işimi sabah yapıyorum."},{"who":"Me","en":"Third, I walk for thirty minutes every day.","tr":"Üçüncüsü, her gün otuz dakika yürüyorum."},{"who":"Me","en":"A startup is a long race, not a short one.","tr":"Girişim kısa değil, uzun bir yarıştır."}],"vocab":[{"en":"tired","tr":"yorgun","ex":"In my first year, I was always tired."},{"en":"rule","tr":"kural","ex":"Now I have three simple rules."},{"en":"at least","tr":"en az","ex":"I sleep at least seven hours."},{"en":"important","tr":"önemli","ex":"I do my most important work in the morning."},{"en":"every day","tr":"her gün","ex":"I walk every day."},{"en":"race","tr":"yarış","ex":"A startup is a long race."}],"grammar":{"title":"Present simple for habits","tr":"Her gün yaptığımız alışkanlıkları anlatmak için present simple kullanılır: I sleep, I walk, I do. 'Every day' ve 'in the morning' gibi zaman ifadeleri genelde cümlenin sonuna gelir.","examples":["I sleep at least seven hours.","I walk for thirty minutes every day.","I do my most important work in the morning."]},"questions":[{"q":"How many rules does the founder have?","options":["Two","Five","Three"],"a":2},{"q":"When does the founder do the most important work?","options":["In the morning","At night","After lunch"],"a":0},{"q":"How long does the founder walk every day?","options":["Ten minutes","Thirty minutes","Two hours"],"a":1}],"gaps":[{"s":"A ___ brain is a slow brain.","a":"tired","hint":"yorgun"},{"s":"I sleep at ___ seven hours.","a":"least","hint":"en az"},{"s":"I walk for thirty minutes every ___.","a":"day","hint":"gün"}],"order":[{"a":"Now I have three simple rules."},{"a":"I walk for thirty minutes every day."}],"translate":[{"tr":"En az yedi saat uyuyorum.","en":"I sleep at least seven hours.","keys":["sleep","at least"]},{"tr":"Gece ondan sonra e-posta okumuyorum.","en":"I do not read emails after ten at night.","keys":["emails","after ten"]}],"roleplay":{"persona":"Young founder","personaTr":"Genç kurucu","scene":"Genç bir girişimci çok yorgun. Ona kendi kurallarını anlatıyorsun.","turns":[{"ai":"I am always tired. What can I do?","aiTr":"Hep yorgunum. Ne yapabilirim?","hint":"Sleep at least seven hours every night.","keys":["sleep","seven hours","at least"]},{"ai":"When can I do my important work?","aiTr":"Önemli işlerimi ne zaman yapabilirim?","hint":"Do it in the morning, before meetings.","keys":["morning","before meetings"]},{"ai":"Anything else?","aiTr":"Başka bir şey var mı?","hint":"Walk for thirty minutes every day.","keys":["walk","thirty minutes","every day"]}]}}};
